INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l21','in conflict with','',NULL,'/ɪn ˈkɑːnflɪkt wɪð/','The hero is in conflict with his world.','这英雄与他的世界相冲突。','Her wishes were in conflict with his.','她的愿望与他的相冲突。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l21','rooted in','',NULL,'/ˈruːtɪd ɪn/','His hero was rooted in real memories.','他的英雄扎根于真实的记忆。','The custom is rooted in history.','这一习俗根植于历史。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l21','along the way','',NULL,'/əˈlɔːŋ ðə weɪ/','He broke a few rules along the way.','一路上他打破了几条规矩。','We learned a lot along the way.','一路走来我们学到很多。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l21','a code to live by','',NULL,'/ə koʊd tə lɪv baɪ/','Audiences wanted a code to live by.','观众想要一套可以依循的准则。','Everyone needs a code to live by.','人人都需要一套行为准则。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp1','choice','{"stem":"\"Myth and fact ___ meet in the Western hero''s story.\"(用助动词强调动词‘确实相遇’,一般过去时,填这个助动词)","options":["did","has","done","was"],"answer_index":0,"stem_cn":"神话与事实在西部英雄的故事里确实相遇了。","explanation_cn":"助动词 do/did + 动词原形,强调‘确实…’;一般过去时用 did + meet。✓ Myth and fact did meet. ✗ was / has / done:强调过去动作用 did + 原形。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp1','choice','{"stem":"\"He ___ know the old West, having lived there as a boy.\"(用助动词强调动词,一般过去,填助动词)","options":["was","has","did","done"],"answer_index":2,"stem_cn":"他确实了解旧西部,因为小时候在那儿住过。","explanation_cn":"助动词 did + 动词原形,强调‘确实…’。✓ He did know the old West. ✗ was / has / done:强调过去动作用 did + 原形。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp1','choice','{"stem":"\"Audiences ___ love that lonely hero even today.\"(用助动词强调动词,一般现在复数,填助动词)","options":["does","did","done","do"],"answer_index":3,"stem_cn":"观众如今确实仍爱那个孤独的英雄。","explanation_cn":"助动词 do + 动词原形,强调‘确实…’;复数一般现在用 do。✓ Audiences do love that hero. ✗ does(单数)/ did(时态需现在)/ done:复数现在用 do + 原形。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp2','choice','{"stem":"\"The honest cowboy wrongly ___ still won the crowd''s heart.\"(过去分词作定语,‘被冤枉陷害的’;frame 的过去分词)","options":["to frame","frame","framed","framing"],"answer_index":2,"stem_cn":"被冤枉陷害的老实牛仔仍赢得了观众的心。","explanation_cn":"过去分词作定语,表被动‘被冤枉陷害的’;frame 的过去分词 framed。✓ the honest cowboy wrongly framed. ✗ framing(主动)/ frame / to frame:被动定语用过去分词。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp2','choice','{"stem":"\"The man ___ from his land became a wanderer.\"(过去分词作定语,‘被剥夺继承权的’;disinherit 的过去分词)","options":["to disinherit","disinherited","disinheriting","disinherit"],"answer_index":1,"stem_cn":"被剥夺了土地的人成了流浪者。","explanation_cn":"过去分词作定语,表被动‘被剥夺继承权的’;disinherit 的过去分词 disinherited。✓ the man disinherited from his land. ✗ disinheriting(主动)/ disinherit / to disinherit:被动定语用过去分词。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp2','choice','{"stem":"\"The frontier, long ___, lives on in his films.\"(过去分词作定语,‘已消失的’;vanish 的过去分词)","options":["to vanish","vanish","vanishing","vanished"],"answer_index":3,"stem_cn":"早已消失的边疆,在他的影片里依然存续。","explanation_cn":"过去分词作定语,表‘已消失的’(状态);vanish 的过去分词 vanished。✓ the frontier, long vanished, … ✗ vanishing(正在)/ vanish / to vanish:表已完成状态用过去分词。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp3','choice','{"stem":"\"Audiences found ___ easy to forgive the good-bad man.\"(find + ___ + 形容词 + to do:填形式宾语)","options":["this","it","them","that"],"answer_index":1,"stem_cn":"观众觉得原谅这好坏参半的人很容易。","explanation_cn":"find + it(形式宾语)+ 形容词 + to do;真正的对象是后面的不定式,先用 it 占位。✓ found it easy to forgive the man. ✗ that / this / them:形式宾语用 it。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp3','choice','{"stem":"\"They found it ___ to escape into a simpler time.\"(find it + 形容词 + to do,填形容词)","options":["pleasure","pleasantly","please","pleasant"],"answer_index":3,"stem_cn":"他们觉得逃进一个更单纯的时代很惬意。","explanation_cn":"find it + 形容词 + to do;填形容词 pleasant。✓ found it pleasant to escape. ✗ pleasantly(副词)/ pleasure(名词)/ please(动词):此处用形容词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp3','choice','{"stem":"\"We still think it ___ to have a code to live by.\"(think it + 形容词 + to do,填形容词)","options":["importance","important","impose","importantly"],"answer_index":1,"stem_cn":"我们仍认为有一套准则可循很重要。","explanation_cn":"think it + 形容词 + to do;填形容词 important。✓ think it important to have a code. ✗ importantly(副词)/ importance(名词)/ impose(动词):此处用形容词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp4','choice','{"stem":"\"___ they wanted was to escape into a plainer time.\"(名词从句作主语,‘所…的’)","options":["Which","That","What","Whether"],"answer_index":2,"stem_cn":"他们想要的,是逃进一个更质朴的时代。","explanation_cn":"名词从句作全句开头,‘所…的’;What=the thing that。✓ What they wanted was to escape. ✗ That / Which / Whether:此处用 What。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp4','choice','{"stem":"\"That hero was exactly ___ the audience longed for.\"(名词从句,‘所…的’)","options":["how","that","which","what"],"answer_index":3,"stem_cn":"那个英雄正是观众所渴望的。","explanation_cn":"名词从句,‘所…的’;was exactly what …。✓ exactly what the audience longed for. ✗ that / which / how:此处用 what。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp4','choice','{"stem":"\"___ makes the Western last is its simple moral code.\"(名词从句作主语,‘…的东西’)","options":["That","What","Which","Whether"],"answer_index":1,"stem_cn":"让西部片长盛不衰的,是它简单的道德准则。","explanation_cn":"名词从句作全句开头,‘…的东西’。✓ What makes the Western last is its code. ✗ That / Which / Whether:此处用 What。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp5','choice','{"stem":"\"Men ___ had struggled against the wild were bewildered.\"(定语从句,指人作主语,填关系词)","options":["whose","which","what","who"],"answer_index":3,"stem_cn":"曾与荒野搏斗的人们感到困惑。","explanation_cn":"定语从句先行词 Men(指人),关系词作主语,用 who。✓ Men who had struggled against the wild. ✗ which(指物)/ what / whose:指人作主语用 who。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp5','choice','{"stem":"\"The star ___ had lived in the West knew it well.\"(定语从句,指人作主语,填关系词)","options":["which","what","who","whom"],"answer_index":2,"stem_cn":"曾在西部生活过的那位明星深知西部。","explanation_cn":"定语从句先行词 the star(指人),从句中作主语,用 who。✓ The star who had lived in the West. ✗ which / what / whom:指人作主语用 who。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp5','choice','{"stem":"\"People ___ had lost their old world clung to his films.\"(定语从句,指人作主语,填关系词)","options":["who","which","what","whose"],"answer_index":0,"stem_cn":"失去了旧世界的人们紧紧抓住他的影片。","explanation_cn":"定语从句先行词 People(指人),从句中作主语,用 who。✓ People who had lost their old world. ✗ which / what / whose:指人作主语用 who。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp6','choice','{"stem":"\"A person who breaks the law and lives outside it is an ___.\"(“逃犯、亡命之徒”用哪个词)","options":["author","outlaw","officer","artist"],"answer_index":1,"stem_cn":"触犯法律、逍遥法外的人。","explanation_cn":"触犯法律、逍遥法外的人是 outlaw(逃犯)。✓ a person who lives outside the law is an outlaw. ✗ officer 警官;✗ author 作者;✗ artist 艺术家——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp6','choice','{"stem":"\"The main character in a film or story is the ___.\"(“主角、主人公”用哪个词)","options":["protagonist","author","audience","critic"],"answer_index":0,"stem_cn":"影片或故事里的主要人物。","explanation_cn":"影片或故事里的主要人物是 protagonist(主角)。✓ the main character is the protagonist. ✗ audience 观众;✗ author 作者;✗ critic 评论家——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',5,'am4_l21_gp6','choice','{"stem":"\"Highest in rank, power, or quality means ___.\"(“至高的、最高的”用哪个词)","options":["equal","minor","supreme","common"],"answer_index":2,"stem_cn":"地位、权力或品质最高的。","explanation_cn":"地位、权力或品质最高的是 supreme(至高的)。✓ highest in rank means supreme. ✗ common 普通;✗ minor 次要;✗ equal 相等——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',6,NULL,'choice','{"stem":"protagonist 的意思是:","options":["作者","主角,主人公","观众","反派"],"answer_index":1,"explanation_cn":"protagonist = 主角、主人公。✓ the protagonist he played."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',6,NULL,'choice','{"stem":"outlaw 的意思是:","options":["律师","法官","逃犯,亡命之徒","警官"],"answer_index":2,"explanation_cn":"outlaw = 逃犯、亡命之徒。✓ the accidental outlaw."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',6,NULL,'choice','{"stem":"mythology 的意思是:","options":["地理","神话(总称)","科学","历史"],"answer_index":1,"explanation_cn":"mythology = 神话(总称)。✓ the history and mythology of the frontier."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',6,NULL,'choice','{"stem":"vicious 的意思是:","options":["恶毒的,凶残的","善良的","温和的","诚实的"],"answer_index":0,"explanation_cn":"vicious = 恶毒的、凶残的。✓ made suspect by vicious gossip."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',6,NULL,'choice','{"stem":"bewilder 的意思是:","options":["使高兴","使平静","使迷惑,使不知所措","使清醒"],"answer_index":2,"explanation_cn":"bewilder = 使迷惑、使不知所措。✓ were bewildered by the new order."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',6,NULL,'choice','{"stem":"taboo 的意思是:","options":["假期","习惯","礼物","禁忌,忌讳"],"answer_index":3,"explanation_cn":"taboo = 禁忌、忌讳。✓ alien taboos they had never agreed to."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',7,NULL,'cloze','{"stem":"第 1 空","context":"It was Corliss ___1___ created the Western formula. His hero was rooted ___2___ real memories. Men who ___3___ struggled against the wild were bewildered by the new order. ___4___ audiences wanted was a simple code to live by.","blank_no":1,"options":["who","which","what","whose"],"answer_index":0,"explanation_cn":"强调句 It was + 人 + who …;指人用 who。✓ It was Corliss who created the formula."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',7,NULL,'cloze','{"stem":"第 2 空","context":"It was Corliss ___1___ created the Western formula. His hero was rooted ___2___ real memories. Men who ___3___ struggled against the wild were bewildered by the new order. ___4___ audiences wanted was a simple code to live by.","blank_no":2,"options":["in","on","at","of"],"answer_index":0,"explanation_cn":"rooted in:‘扎根于、源自’;固定搭配用 in。✓ His hero was rooted in real memories."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',7,NULL,'cloze','{"stem":"第 3 空","context":"It was Corliss ___1___ created the Western formula. His hero was rooted ___2___ real memories. Men who ___3___ struggled against the wild were bewildered by the new order. ___4___ audiences wanted was a simple code to live by.","blank_no":3,"options":["had","have","has","was"],"answer_index":0,"explanation_cn":"定语从句里用过去完成 had + 过去分词,表比主句更早的过去。✓ Men who had struggled against the wild."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',7,NULL,'cloze','{"stem":"第 4 空","context":"It was Corliss ___1___ created the Western formula. His hero was rooted ___2___ real memories. Men who ___3___ struggled against the wild were bewildered by the new order. ___4___ audiences wanted was a simple code to live by.","blank_no":4,"options":["What","That","Which","Whether"],"answer_index":0,"explanation_cn":"名词从句作全句开头,‘所…的’。✓ What audiences wanted was a simple code."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',8,NULL,'choice','{"stem":"How did Corliss''s childhood prepare him for his Western roles?","options":["He studied acting in school","He had read many books","He had lived in the old West as a boy, so his hero was rooted in real memories","He grew up in a big city"],"answer_index":2,"explanation_cn":"录音说科利斯的银幕英雄之所以真实,是因为他小时候在旧西部生活过,英雄扎根于真实记忆。✓ lived in the West as a boy."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',8,NULL,'choice','{"stem":"What kind of character did Corliss usually play?","options":["A cheerful town mayor","A famous singer","A wealthy banker","The good-bad man, an outsider at war with himself and the frontier"],"answer_index":3,"explanation_cn":"录音说科利斯常演‘好坏参半的人’,一个与自己、也与边疆为敌的孤独局外人。✓ good-bad man, outsider."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',8,NULL,'choice','{"stem":"Why did early audiences forgive the good-bad man''s faults?","options":["They found it easy to understand him and longed for a simpler time","They never noticed his faults","He never broke any rule","He was always rich"],"answer_index":0,"explanation_cn":"录音说早年观众容易理解并原谅这好坏参半的人,又渴望逃回一个更单纯的时代。✓ easy to forgive, longed for simpler time."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',9,NULL,'choice','{"stem":"你想说\"神话与事实确实在他的故事里相遇了\"(do/did 强调):","options":["Myth and fact did meet in his story.","Myth and fact did meeting in his story.","Myth and fact does meet in his story.","Myth and fact did met in his story."],"answer_index":0,"explanation_cn":"用 did + 动词原形 meet 表强调‘确实…’;meet 用原形(不用过去式 met)、不用 does(时态需过去)、不用 -ing。✓ did meet. 场合:强调‘确实做了…’。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',9,NULL,'choice','{"stem":"你想说\"他们想要的,是逃进一个更质朴的时代\"(what 名词从句):","options":["What they wanted were to escape into a plainer time.","That they wanted was to escape into a plainer time.","What did they want was to escape into a plainer time.","What they wanted was to escape into a plainer time."],"answer_index":3,"explanation_cn":"What 引导名词从句作全句开头;全句的动词用 was(单数,不用 were)、不用 That、从句内用陈述语序(不写 did they want)。✓ What they wanted was … 场合:说“…的,是…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',9,NULL,'choice','{"stem":"你想说\"曾与荒野搏斗的人们感到困惑\"(who + 过去完成):","options":["Men who had struggle against the wild were bewildered.","Men who have struggled against the wild were bewildered.","Men who had struggled against the wild were bewildered.","Men which had struggled against the wild were bewildered."],"answer_index":2,"explanation_cn":"who 引导、指人;从句用过去完成 had + 过去分词 struggled(不用 have、struggle 须用过去分词 struggled)、不用 which。✓ Men who had struggled … 场合:说“曾…的人们”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',10,NULL,'choice','{"stem":"protagonist 的意思是:","options":["作者","主角,主人公","反派","观众"],"answer_index":1,"explanation_cn":"protagonist = 主角、主人公。✓ the protagonist he played."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',10,NULL,'choice','{"stem":"bewilder 的意思是:","options":["使清醒","使平静","使高兴","使迷惑,使不知所措"],"answer_index":3,"explanation_cn":"bewilder = 使迷惑、使不知所措。✓ were bewildered by the new order."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',10,NULL,'choice','{"stem":"\"Myth and fact ___ meet in his story.\"(用助动词强调动词,一般过去)","options":["done","did","was","has"],"answer_index":1,"stem_cn":"神话与事实确实在他的故事里相遇了。","explanation_cn":"助动词 did + 动词原形,强调‘确实…’。✓ Myth and fact did meet. ✗ was / has / done。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',10,NULL,'choice','{"stem":"\"___ they wanted was a simple code.\"(名词从句作全句开头)","options":["That","Whether","Which","What"],"answer_index":3,"stem_cn":"他们想要的,是一套简单的准则。","explanation_cn":"名词从句作全句开头,‘所…的’。✓ What they wanted was a simple code. ✗ That / Which / Whether。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',10,NULL,'choice','{"stem":"\"rooted in\" 的意思是:","options":["拔起","漂浮于","根植于、源自","远离"],"answer_index":2,"explanation_cn":"rooted in = 根植于、源自。✓ his hero was rooted in real memories."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',10,NULL,'choice','{"stem":"\"a code to live by\" 的意思是:","options":["一段密码","可遵循的行为准则","一条法律","一本书"],"answer_index":1,"explanation_cn":"a code to live by = 可遵循的行为准则。✓ they wanted a code to live by."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',10,NULL,'choice','{"stem":"According to the passage, what made Corliss different from later stars?","options":["He never rode a horse","He directed his own films","He was much richer","He appeared in nothing but Westerns and had truly known the old West"],"answer_index":3,"passage":"Wade Corliss was, in his day, the supreme star of the early Western — for while the smoother, more famous cowboys who came after him appeared in every kind of picture, Corliss appeared in nothing but Westerns. Through the silent years he stood unchallenged. It was Corliss who first shaped the basic formula of the Western film, and it was Corliss who designed the protagonist he played in picture after picture: the good-bad man, the accidental outlaw, the honest cowboy wrongly framed, the sheriff turned suspect by vicious gossip — in short, the lone individual at war with himself and with the harsh frontier around him. Unlike most of the studio men of his time, Corliss actually knew something of the old West. He had lived in it as a boy, in the very years when it was already fading, and so his hero was rooted firmly in his own memories and in the history and mythology of a vanished frontier. And although no chapter of the national past has been more absurdly romanticized, myth and fact did meet in at least one place: the clash between the free individual and an encroaching, tidy civilization. Men who had spent their lives struggling against the weather and the wilderness were bewildered by the new order of politicians and bankers, and hemmed in by fences, by written laws, by alien taboos they had never agreed to. Corliss''s good-bad man was forever an outsider, one of the disinherited; and if, along the way, he sometimes crossed the line the town had drawn, the early audiences found it easy to understand and to forgive. What they wanted, sitting in the dark, was to escape into a plainer time — and, more than that, they wanted a simple code to live by. We want it still.","explanation_cn":"课文说科利斯与后来的明星不同:他只演西部片,而且真正了解旧西部(小时候在那儿住过)。✓ only Westerns, knew the old West."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',10,NULL,'choice','{"stem":"What was Corliss''s good-bad man always?","options":["A wealthy landowner","An outsider, one of the disinherited","A city banker","A cheerful farmer"],"answer_index":1,"passage":"Wade Corliss was, in his day, the supreme star of the early Western — for while the smoother, more famous cowboys who came after him appeared in every kind of picture, Corliss appeared in nothing but Westerns. Through the silent years he stood unchallenged. It was Corliss who first shaped the basic formula of the Western film, and it was Corliss who designed the protagonist he played in picture after picture: the good-bad man, the accidental outlaw, the honest cowboy wrongly framed, the sheriff turned suspect by vicious gossip — in short, the lone individual at war with himself and with the harsh frontier around him. Unlike most of the studio men of his time, Corliss actually knew something of the old West. He had lived in it as a boy, in the very years when it was already fading, and so his hero was rooted firmly in his own memories and in the history and mythology of a vanished frontier. And although no chapter of the national past has been more absurdly romanticized, myth and fact did meet in at least one place: the clash between the free individual and an encroaching, tidy civilization. Men who had spent their lives struggling against the weather and the wilderness were bewildered by the new order of politicians and bankers, and hemmed in by fences, by written laws, by alien taboos they had never agreed to. Corliss''s good-bad man was forever an outsider, one of the disinherited; and if, along the way, he sometimes crossed the line the town had drawn, the early audiences found it easy to understand and to forgive. What they wanted, sitting in the dark, was to escape into a plainer time — and, more than that, they wanted a simple code to live by. We want it still.","explanation_cn":"课文说科利斯那好坏参半的人永远是个局外人,是被剥夺了产业的人之一。✓ outsider, disinherited."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',10,NULL,'choice','{"stem":"Where was Corliss''s screen hero rooted?","options":["In foreign lands","In the big cities","In books he had read","In his own memories and the mythology of the vanished frontier"],"answer_index":3,"audio":"Wade Corliss was, in his day, the supreme star of the early Western — for while the smoother, more famous cowboys who came after him appeared in every kind of picture, Corliss appeared in nothing but Westerns. Through the silent years he stood unchallenged. It was Corliss who first shaped the basic formula of the Western film, and it was Corliss who designed the protagonist he played in picture after picture: the good-bad man, the accidental outlaw, the honest cowboy wrongly framed, the sheriff turned suspect by vicious gossip — in short, the lone individual at war with himself and with the harsh frontier around him. Unlike most of the studio men of his time, Corliss actually knew something of the old West. He had lived in it as a boy, in the very years when it was already fading, and so his hero was rooted firmly in his own memories and in the history and mythology of a vanished frontier. And although no chapter of the national past has been more absurdly romanticized, myth and fact did meet in at least one place: the clash between the free individual and an encroaching, tidy civilization. Men who had spent their lives struggling against the weather and the wilderness were bewildered by the new order of politicians and bankers, and hemmed in by fences, by written laws, by alien taboos they had never agreed to. Corliss''s good-bad man was forever an outsider, one of the disinherited; and if, along the way, he sometimes crossed the line the town had drawn, the early audiences found it easy to understand and to forgive. What they wanted, sitting in the dark, was to escape into a plainer time — and, more than that, they wanted a simple code to live by. We want it still.","explanation_cn":"课文说科利斯的银幕英雄扎根于他自己的记忆,以及那片消失边疆的历史与神话。✓ memories and mythology of the frontier."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l21',10,NULL,'choice','{"stem":"What did early audiences long for, according to the speaker?","options":["To escape into a simpler time and to have a code to live by","To forget the past","To leave the country","To become rich quickly"],"answer_index":0,"audio":"Wade Corliss was, in his day, the supreme star of the early Western — for while the smoother, more famous cowboys who came after him appeared in every kind of picture, Corliss appeared in nothing but Westerns. Through the silent years he stood unchallenged. It was Corliss who first shaped the basic formula of the Western film, and it was Corliss who designed the protagonist he played in picture after picture: the good-bad man, the accidental outlaw, the honest cowboy wrongly framed, the sheriff turned suspect by vicious gossip — in short, the lone individual at war with himself and with the harsh frontier around him. Unlike most of the studio men of his time, Corliss actually knew something of the old West. He had lived in it as a boy, in the very years when it was already fading, and so his hero was rooted firmly in his own memories and in the history and mythology of a vanished frontier. And although no chapter of the national past has been more absurdly romanticized, myth and fact did meet in at least one place: the clash between the free individual and an encroaching, tidy civilization. Men who had spent their lives struggling against the weather and the wilderness were bewildered by the new order of politicians and bankers, and hemmed in by fences, by written laws, by alien taboos they had never agreed to. Corliss''s good-bad man was forever an outsider, one of the disinherited; and if, along the way, he sometimes crossed the line the town had drawn, the early audiences found it easy to understand and to forgive. What they wanted, sitting in the dark, was to escape into a plainer time — and, more than that, they wanted a simple code to live by. We want it still.","explanation_cn":"课文说早年观众渴望逃进一个更单纯的时代,更想要一套可以依循的简单准则。✓ escape to simpler time, a code to live by."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l22',4,4,22,'Knowledge and Progress','知识与进步','not only … but also …(+ 被动)、the moment / the instant 引导的时间从句(一…就)、more and more + 形容词 / 比较级 + and + 比较级、be to do(what are we to do…)、what 引导的名词从句(What we call … is …)(NCE4 无 KS 页,考点由课文结构自取;IP:源为 G.N.M.蒂勒尔《人的个性》,内容为‘进步即知识累积、智力与道德无进步’的论述,已用 100% 原创行文复述,无逐句改写、无人物;题材=知识与进步的思辨·无害;美语化 civilization/recognize;第四册第22课)','为什么“进步”这个念头在现代人心里显得那么大?一种特定的进步确实正在我们四周发生,而且一年比一年更加显眼。诚然,在智力与道德上,人类几乎毫无长进——今天一个聪明的无赖,并不比三千年前一个聪明的无赖更明智、也不更善良。可在一件事上,即知识的堆积上,人类却进步得无可估量。知识最初开始增长,是在一个人能用言语把自己的想法传给另一个人的那一刻。文字被发明出来时,又迈出了远为巨大的一步,因为知识从此不仅能被传递,还能被储存。书本让学校成为可能,学校反过来又充实了更多书本;于是知识以复利的方式成倍增长,而整个过程又因印刷术的到来而被极大地增强。有很长一段时间,步子一直很慢;可随着科学兴起,节奏骤然加快,知识开始按一套刻意的计划堆积起来。原本的涓涓细流变成溪流,溪流此后又涨成了洪流。更妙的是,任何新知识一旦获得,立刻就被投入实用。因此,我们引以为傲、称之为“现代文明”的东西,并不是人性各方面均衡发展的果实;它不过是被储存起来、投入日常生活的知识罢了。于是一个棘手的问题摆在全人类面前:我们该拿这堆起来的知识怎么办?正如人们常说的,知识是一把双刃剑,同样可用于行善或作恶;今天,它正被不加分别地用于两者。谁也说不准,这股永远在增长的双重力量,最终会把我们抬得更高,还是把我们击得粉碎。','{"q":"Listen and answer — In what two areas have people made no ''progress'' at all?","options":["In intelligence and in morality","In science and in writing","In trade and in travel","In printing and in speech"],"answer_index":0}'::jsonb,'{"title":"not only … but also / the moment·the instant / more and more / be to do / what 名词从句","intro":"①not only … but also …(不仅…而且…),可含被动:not only be passed on but also stored。②the moment / the instant 引导时间从句‘一…就…’。③more and more + 形容词;或 比较级 + and + 比较级。④be to do:表将要或‘该…’:what are we to do。⑤what 引导名词从句:What we call ''modern civilization'' is stored-up knowledge。","table":{"headers":["用法","结构","例子"],"rows":[["not only…but also","not only … but also …","not only be passed on but also stored"],["the moment/instant","the moment/instant + 从句","the moment one person could speak"],["more and more","more and more + 形容词","more and more manifest"],["be to do","主语 + be to + 动词原形","what are we to do with it"],["what 名词从句","What … + 谓语","What we call civilization is knowledge"]]},"specialRules":[{"rule":"not only … but also 连接被动时,not only / but also 放在助动词后:could not only be passed on but also (be) stored。","mark":"not only be done but also done"},{"rule":"be to do 表示按计划将要发生或应该、注定:what are we to do = 我们该怎么办。","mark":"be to do"},{"rule":"美式拼写:civilization(文明,英式 civilisation)、recognize(认出,英式 recognise)。本课已按美语写。","mark":"civilization / recognize"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l22',1,NULL,'Why does the idea of progress loom so large in the modern mind? Progress of one particular kind is certainly taking place all around us, and it grows more and more manifest with every passing year. In intelligence and in morality, it is true, the human race has hardly improved at all — a clever rogue of today is no wiser and no kinder than a clever rogue of three thousand years ago.','为什么“进步”这个念头在现代人心里显得那么大?一种特定的进步确实正在我们四周发生,而且一年比一年更加显眼。诚然,在智力与道德上,人类几乎毫无长进——今天一个聪明的无赖,并不比三千年前一个聪明的无赖更明智、也不更善良。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l22',2,NULL,'Yet in one thing, the piling up of knowledge, mankind has advanced beyond all measure. Knowledge first began to grow the moment one person could communicate his thoughts to another by speech. When writing was invented, a far greater step was taken, for now knowledge could not only be passed on but also stored.','可在一件事上,即知识的堆积上,人类却进步得无可估量。知识最初开始增长,是在一个人能用言语把自己的想法传给另一个人的那一刻。文字被发明出来时,又迈出了远为巨大的一步,因为知识从此不仅能被传递,还能被储存。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l22',3,NULL,'Books made schools possible, and schools in their turn filled more books; so knowledge multiplied in the manner of compound interest, and the whole process was enormously enhanced by the coming of printing. For a long while the pace stayed slow; but with the rise of science the tempo was suddenly quickened, and knowledge began to pile up to a deliberate plan.','书本让学校成为可能,学校反过来又充实了更多书本;于是知识以复利的方式成倍增长,而整个过程又因印刷术的到来而被极大地增强。有很长一段时间,步子一直很慢;可随着科学兴起,节奏骤然加快,知识开始按一套刻意的计划堆积起来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l22',4,NULL,'What had been a trickle became a stream, and the stream has since swelled into a torrent. Better still, the instant any new knowledge is gained, it is at once turned to practical use. What we proudly call ''modern civilization'' is not, then, the fruit of a balanced growth of every side of human nature; it is simply stored-up knowledge put to work in daily life.','原本的涓涓细流变成溪流,溪流此后又涨成了洪流。更妙的是,任何新知识一旦获得,立刻就被投入实用。因此,我们引以为傲、称之为“现代文明”的东西,并不是人性各方面均衡发展的果实;它不过是被储存起来、投入日常生活的知识罢了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l22',5,NULL,'And so a hard question now faces all of humanity: what are we to do with the mountain of knowledge we have raised? Knowledge, as people so often remark, is a two-edged weapon, equally fit for good or for evil; today it is being used, indifferently, for both. No one can yet say whether this double power, forever growing, will lift us higher or shatter us in the end.','于是一个棘手的问题摆在全人类面前:我们该拿这堆起来的知识怎么办?正如人们常说的,知识是一把双刃剑,同样可用于行善或作恶;今天,它正被不加分别地用于两者。谁也说不准,这股永远在增长的双重力量,最终会把我们抬得更高,还是把我们击得粉碎。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
