INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l22','loom large','',NULL,'/luːm lɑːrdʒ/','The idea of progress looms large today.','进步的念头如今显得格外突出。','Exams loom large in a student''s life.','考试在学生生活里分量很重。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l22','put to use','',NULL,'/pʊt tə juːs/','New knowledge is at once put to use.','新知识立刻被投入使用。','He put his skills to good use.','他很好地发挥了自己的技能。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l22','pile up','',NULL,'/paɪl ʌp/','Knowledge began to pile up.','知识开始堆积起来。','The work piled up during my holiday.','假期里工作堆了一大堆。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l22','two-edged weapon','',NULL,'/ˈtuː edʒd ˈwepən/','Knowledge is a two-edged weapon.','知识是一把双刃剑。','Fame can be a two-edged weapon.','名声可能是把双刃剑。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp1','choice','{"stem":"\"Knowledge could not only be passed on ___ also stored.\"(not only … ___ also:‘不仅…而且…’,填中间的连词)","options":["than","or","and","but"],"answer_index":3,"stem_cn":"知识不仅能被传递,还能被储存。","explanation_cn":"not only … but also …,‘不仅…而且…’;中间的连词是 but。✓ not only be passed on but also stored. ✗ and / or / than:此结构中间用 but。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp1','choice','{"stem":"\"Writing let knowledge be not only communicated ___ also kept.\"(‘不仅…而且…’,填中间的连词)","options":["so","but","and","or"],"answer_index":1,"stem_cn":"文字让知识不仅得以传播,还得以保存。","explanation_cn":"not only … but also …;中间的连词是 but。✓ not only communicated but also kept. ✗ and / or / so:此结构中间用 but。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp1','choice','{"stem":"\"Science not ___ raised the tempo but also gave it a plan.\"(not ___ … but also:‘不仅…而且…’,填 not 后那个词)","options":["only","even","just","still"],"answer_index":0,"stem_cn":"科学不仅加快了节奏,还给了它一套计划。","explanation_cn":"not only … but also …;not 后那个词是 only。✓ not only raised the tempo but also gave it a plan. ✗ just / even / still:此结构用 not only。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp2','choice','{"stem":"\"Knowledge grew ___ moment one person could speak to another.\"(‘一…就…’= ___ moment …,填 moment 前的词)","options":["a","that","the","this"],"answer_index":2,"stem_cn":"一个人一能对另一个人说话,知识就增长起来。","explanation_cn":"the moment …,‘一…就…’;固定用 the moment。✓ the moment one person could speak. ✗ a / this / that:此结构用 the moment。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp2','choice','{"stem":"\"The ___ new knowledge is gained, it is put to use.\"(‘一…就…’,填表‘瞬间’的名词作连词)","options":["instant","day","week","hour"],"answer_index":0,"stem_cn":"新知识一到手,立刻就被投入使用。","explanation_cn":"the instant …,‘一…就…’;用表‘瞬间’的 instant 作连词。✓ the instant new knowledge is gained. ✗ hour / day / week:此结构用 the instant。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp2','choice','{"stem":"\"Everything changed the ___ science appeared.\"(‘一…就…’,填表‘时刻’的名词作连词)","options":["way","reason","moment","place"],"answer_index":2,"stem_cn":"科学一出现,一切就变了。","explanation_cn":"the moment …,‘一…就…’;用表‘时刻’的 moment 作连词。✓ the moment science appeared. ✗ place / reason / way:此结构用 the moment。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp3','choice','{"stem":"\"The stream of knowledge grew ___ than ever before.\"(比较级 + than;big 的比较级)","options":["biggest","bigger","big","more big"],"answer_index":1,"stem_cn":"知识之流比以往任何时候都更大。","explanation_cn":"比较级 + than,‘更大’;big 的比较级 bigger。✓ grew bigger than ever before. ✗ big(原级)/ biggest(最高级)/ more big:单音节用 -er。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp3','choice','{"stem":"\"Knowledge spreads ___ than it once did.\"(比较级 + than;fast 的比较级)","options":["faster","fast","more fast","fastest"],"answer_index":0,"stem_cn":"知识传播得比从前更快。","explanation_cn":"比较级 + than,‘更快’;fast 的比较级 faster。✓ spreads faster than it once did. ✗ fast / fastest / more fast:单音节用 -er。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp3','choice','{"stem":"\"This power is ___ dangerous than we admit.\"(比较级;dangerous 是多音节形容词,前面加的词)","options":["very","much","most","more"],"answer_index":3,"stem_cn":"这股力量比我们承认的更危险。","explanation_cn":"比较级 + than;dangerous 是多音节形容词,比较级在前面加 more。✓ more dangerous than we admit. ✗ most / much / very:多音节比较级用 more。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp4','choice','{"stem":"\"What are we to ___ with all this knowledge?\"(‘我们该拿…怎么办’,be to + 动词原形,填该动词)","options":["done","do","doing","did"],"answer_index":1,"stem_cn":"我们该拿这么多知识怎么办?","explanation_cn":"be to + 动词原形:what are we to do,‘我们该拿…怎么办’;填原形 do。✓ What are we to do with it? ✗ doing / done / did:be to 后用动词原形。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp4','choice','{"stem":"\"This power is to ___ our future, for good or ill.\"(be to + 动词原形:‘将决定…’,填该动词)","options":["deciding","decided","decide","decides"],"answer_index":2,"stem_cn":"这股力量将决定我们的未来,是福是祸。","explanation_cn":"be to + 动词原形:‘将决定…’;填原形 decide。✓ This power is to decide our future. ✗ decides / deciding / decided:be to 后用动词原形。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp4','choice','{"stem":"\"No one knows what is to be ___ with it.\"(be to be + 过去分词:‘该被…’,填该过去分词)","options":["done","doing","did","do"],"answer_index":0,"stem_cn":"没人知道该拿它怎么办。","explanation_cn":"be to be + 过去分词(被动):‘该被…’;填过去分词 done。✓ what is to be done with it. ✗ do / doing / did:被动用 be done。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp5','choice','{"stem":"\"___ we call ''modern civilization'' is stored-up knowledge.\"(名词从句作主语,‘我们所…的’)","options":["Which","Whether","That","What"],"answer_index":3,"stem_cn":"我们所谓的“现代文明”,就是储存起来的知识。","explanation_cn":"名词从句作全句开头,‘我们所…的’;What=the thing that。✓ What we call ''modern civilization'' is knowledge. ✗ That / Which / Whether:此处用 What。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp5','choice','{"stem":"\"This is exactly ___ science has given us.\"(名词从句,‘所…的’)","options":["that","what","which","how"],"answer_index":1,"stem_cn":"这正是科学给予我们的。","explanation_cn":"名词从句,‘所…的’;exactly what …。✓ exactly what science has given us. ✗ that / which / how:此处用 what。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp5','choice','{"stem":"\"___ mankind has gained is knowledge, not wisdom.\"(名词从句作主语,‘所…的’)","options":["Whether","That","What","Which"],"answer_index":2,"stem_cn":"人类所获得的是知识,而非智慧。","explanation_cn":"名词从句作全句开头,‘所…的’。✓ What mankind has gained is knowledge. ✗ That / Which / Whether:此处用 What。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp6','choice','{"stem":"\"To make something greater or better is to ___ it.\"(“提高、增强”用哪个词)","options":["enhance","hide","destroy","reduce"],"answer_index":0,"stem_cn":"使某物更大或更好。","explanation_cn":"使某物更大或更好是 enhance(提高、增强)。✓ to make something better is to enhance it. ✗ reduce 减少;✗ hide 隐藏;✗ destroy 摧毁——都相反或不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp6','choice','{"stem":"\"A slow, thin flow of liquid is a ___.\"(“涓涓细流”用哪个词)","options":["flood","trickle","storm","wave"],"answer_index":1,"stem_cn":"缓慢细小的水流。","explanation_cn":"缓慢细小的水流是 trickle(涓涓细流)。✓ a slow, thin flow is a trickle. ✗ flood 洪水;✗ wave 波浪;✗ storm 暴风雨——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',5,'am4_l22_gp6','choice','{"stem":"\"Standards of right and wrong conduct are called ___.\"(“道德”用哪个词)","options":["weather","geography","morality","distance"],"answer_index":2,"stem_cn":"关于是非对错的准则。","explanation_cn":"关于是非对错的准则是 morality(道德)。✓ standards of right and wrong are morality. ✗ geography 地理;✗ weather 天气;✗ distance 距离——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',6,NULL,'choice','{"stem":"morality 的意思是:","options":["道德","天气","距离","财富"],"answer_index":0,"explanation_cn":"morality = 道德。✓ in intelligence and in morality."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',6,NULL,'choice','{"stem":"enhance 的意思是:","options":["摧毁","降低","隐藏","提高,增强"],"answer_index":3,"explanation_cn":"enhance = 提高、增强。✓ enormously enhanced by printing."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',6,NULL,'choice','{"stem":"tempo 的意思是:","options":["重量","高度","节奏,速度","颜色"],"answer_index":2,"explanation_cn":"tempo = 节奏、速度。✓ the tempo was suddenly quickened."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',6,NULL,'choice','{"stem":"torrent 的意思是:","options":["水滴","池塘","细流","激流,洪流"],"answer_index":3,"explanation_cn":"torrent = 激流、洪流。✓ swelled into a torrent."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',6,NULL,'choice','{"stem":"loom 的意思是:","options":["漂浮","消失","(隐约)呈现,逼近","沉睡"],"answer_index":2,"explanation_cn":"loom = (隐约)呈现、逼近。✓ the idea of progress loom so large."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',6,NULL,'choice','{"stem":"shatter 的意思是:","options":["修复","粉碎,击碎","建造","连接"],"answer_index":1,"explanation_cn":"shatter = 粉碎、击碎。✓ shatter us in the end."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',7,NULL,'cloze','{"stem":"第 1 空","context":"Progress grows ever ___1___ manifest each year. Knowledge could not only be passed on ___2___ also stored. ___3___ we call civilization is stored-up knowledge. It is a two-edged weapon; what is to be ___4___ with it?","blank_no":1,"options":["more","most","much","very"],"answer_index":0,"explanation_cn":"ever more + 形容词,‘愈发…、越来越…’;此处填比较级词 more。✓ grows ever more manifest each year."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',7,NULL,'cloze','{"stem":"第 2 空","context":"Progress grows ever ___1___ manifest each year. Knowledge could not only be passed on ___2___ also stored. ___3___ we call civilization is stored-up knowledge. It is a two-edged weapon; what is to be ___4___ with it?","blank_no":2,"options":["but","and","or","than"],"answer_index":0,"explanation_cn":"not only … but also …,‘不仅…而且…’;中间用 but。✓ not only be passed on but also stored."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',7,NULL,'cloze','{"stem":"第 3 空","context":"Progress grows ever ___1___ manifest each year. Knowledge could not only be passed on ___2___ also stored. ___3___ we call civilization is stored-up knowledge. It is a two-edged weapon; what is to be ___4___ with it?","blank_no":3,"options":["What","That","Which","Whether"],"answer_index":0,"explanation_cn":"名词从句作全句开头,‘我们所…的’。✓ What we call civilization is stored-up knowledge."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',7,NULL,'cloze','{"stem":"第 4 空","context":"Progress grows ever ___1___ manifest each year. Knowledge could not only be passed on ___2___ also stored. ___3___ we call civilization is stored-up knowledge. It is a two-edged weapon; what is to be ___4___ with it?","blank_no":4,"options":["done","do","doing","did"],"answer_index":0,"explanation_cn":"be to be + 过去分词(被动):‘该被…’。✓ what is to be done with it."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',8,NULL,'choice','{"stem":"In what two areas has mankind made no real progress?","options":["In printing and in books","In science and in writing","In intelligence and in morality","In cities and in trade"],"answer_index":2,"explanation_cn":"录音说人类在智力和道德这两方面几乎毫无长进。✓ intelligence and morality."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',8,NULL,'choice','{"stem":"What does the speaker say ''modern civilization'' really is?","options":["An accident of history","Stored-up knowledge applied to practical life","A gift of nature","A balanced growth of all human nature"],"answer_index":1,"explanation_cn":"录音说所谓‘现代文明’其实只是储存起来、投入日常生活的知识。✓ stored-up knowledge in practical life."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',8,NULL,'choice','{"stem":"How is new knowledge treated as soon as it is gained?","options":["It is at once turned to practical use","It is forgotten","It is hidden away","It is destroyed"],"answer_index":0,"explanation_cn":"录音说任何新知识一旦获得,立刻就被投入实用。✓ at once turned to practical use."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',9,NULL,'choice','{"stem":"你想说\"知识不仅能被传递,还能被储存\"(not only … but also + 被动):","options":["Knowledge could not only passed on but also stored.","Knowledge could not only be passed on but also stored.","Knowledge could not only be passed on but also store.","Knowledge could not only be passed on but also to store."],"answer_index":1,"explanation_cn":"not only … but also 连接被动:not only be passed on but also (be) stored;store 用过去分词 stored、不能少 be、也不写成 to store。✓ not only be passed on but also stored. 场合:说“不仅…而且…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',9,NULL,'choice','{"stem":"你想说\"一个人一能对另一个人说话,知识就增长起来\"(the moment):","options":["Knowledge grew the moment one person could speak to another.","Knowledge grew a moment one person could speak to another.","Knowledge grew the moment one person could speaks to another.","Knowledge grew the moment when one person could speaking to another."],"answer_index":0,"explanation_cn":"the moment‘一…就…’引导时间从句;could 后用原形 speak(不用 speaks / speaking)、不加 when、用 the 不用 a。✓ the moment one person could speak … 场合:说“一…就…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',9,NULL,'choice','{"stem":"你想说\"我们所谓的''现代文明'',就是储存起来的知识\"(what 名词从句):","options":["That we call ''modern civilization'' is stored-up knowledge.","What do we call ''modern civilization'' is stored-up knowledge.","What we call ''modern civilization'' are stored-up knowledge.","What we call ''modern civilization'' is stored-up knowledge."],"answer_index":3,"explanation_cn":"What 引导名词从句作全句开头;全句的动词用 is(单数,不用 are)、不用 That、从句内用陈述语序(不写 do we call)。✓ What we call … is … 场合:说“我们所谓的…,是…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',10,NULL,'choice','{"stem":"morality 的意思是:","options":["距离","财富","天气","道德"],"answer_index":3,"explanation_cn":"morality = 道德。✓ in intelligence and in morality."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',10,NULL,'choice','{"stem":"torrent 的意思是:","options":["激流,洪流","细流","池塘","水滴"],"answer_index":0,"explanation_cn":"torrent = 激流、洪流。✓ swelled into a torrent."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',10,NULL,'choice','{"stem":"\"Knowledge could not only be passed on ___ also stored.\"(‘不仅…而且…’,填 not only 之后、also 之前的连词)","options":["than","and","or","but"],"answer_index":3,"stem_cn":"知识不仅能被传递,还能被储存。","explanation_cn":"not only … but also …,‘不仅…而且…’;中间用 but。✓ not only be passed on but also stored. ✗ and / or / than。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',10,NULL,'choice','{"stem":"\"___ we call civilization is stored-up knowledge.\"(名词从句作全句开头)","options":["What","Whether","That","Which"],"answer_index":0,"stem_cn":"我们所谓的文明,就是储存起来的知识。","explanation_cn":"名词从句作全句开头,‘我们所…的’。✓ What we call civilization is stored-up knowledge. ✗ That / Which / Whether。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',10,NULL,'choice','{"stem":"\"loom large\" 的意思是:","options":["消失不见","缓慢移动","微不足道","显得突出、令人瞩目"],"answer_index":3,"explanation_cn":"loom large = 显得突出、令人瞩目。✓ the idea of progress looms large."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',10,NULL,'choice','{"stem":"\"put to use\" 的意思是:","options":["藏起来","卖掉","加以利用","放在一边"],"answer_index":2,"explanation_cn":"put to use = 加以利用。✓ new knowledge is put to use."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',10,NULL,'choice','{"stem":"According to the passage, in what two things has mankind NOT improved?","options":["In intelligence and in morality","In knowledge and in printing","In science and in speech","In books and in schools"],"answer_index":0,"passage":"Why does the idea of progress loom so large in the modern mind? Progress of one particular kind is certainly taking place all around us, and it grows more and more manifest with every passing year. In intelligence and in morality, it is true, the human race has hardly improved at all — a clever rogue of today is no wiser and no kinder than a clever rogue of three thousand years ago. Yet in one thing, the piling up of knowledge, mankind has advanced beyond all measure. Knowledge first began to grow the moment one person could communicate his thoughts to another by speech. When writing was invented, a far greater step was taken, for now knowledge could not only be passed on but also stored. Books made schools possible, and schools in their turn filled more books; so knowledge multiplied in the manner of compound interest, and the whole process was enormously enhanced by the coming of printing. For a long while the pace stayed slow; but with the rise of science the tempo was suddenly quickened, and knowledge began to pile up to a deliberate plan. What had been a trickle became a stream, and the stream has since swelled into a torrent. Better still, the instant any new knowledge is gained, it is at once turned to practical use. What we proudly call ''modern civilization'' is not, then, the fruit of a balanced growth of every side of human nature; it is simply stored-up knowledge put to work in daily life. And so a hard question now faces all of humanity: what are we to do with the mountain of knowledge we have raised? Knowledge, as people so often remark, is a two-edged weapon, equally fit for good or for evil; today it is being used, indifferently, for both. No one can yet say whether this double power, forever growing, will lift us higher or shatter us in the end.","explanation_cn":"课文说人类在智力与道德这两件事上几乎毫无长进。✓ intelligence and morality."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',10,NULL,'choice','{"stem":"What does the passage say ''modern civilization'' is?","options":["A balanced development of human nature","The gift of a few great men","Accumulated knowledge applied to practical life","The result of good morality"],"answer_index":2,"passage":"Why does the idea of progress loom so large in the modern mind? Progress of one particular kind is certainly taking place all around us, and it grows more and more manifest with every passing year. In intelligence and in morality, it is true, the human race has hardly improved at all — a clever rogue of today is no wiser and no kinder than a clever rogue of three thousand years ago. Yet in one thing, the piling up of knowledge, mankind has advanced beyond all measure. Knowledge first began to grow the moment one person could communicate his thoughts to another by speech. When writing was invented, a far greater step was taken, for now knowledge could not only be passed on but also stored. Books made schools possible, and schools in their turn filled more books; so knowledge multiplied in the manner of compound interest, and the whole process was enormously enhanced by the coming of printing. For a long while the pace stayed slow; but with the rise of science the tempo was suddenly quickened, and knowledge began to pile up to a deliberate plan. What had been a trickle became a stream, and the stream has since swelled into a torrent. Better still, the instant any new knowledge is gained, it is at once turned to practical use. What we proudly call ''modern civilization'' is not, then, the fruit of a balanced growth of every side of human nature; it is simply stored-up knowledge put to work in daily life. And so a hard question now faces all of humanity: what are we to do with the mountain of knowledge we have raised? Knowledge, as people so often remark, is a two-edged weapon, equally fit for good or for evil; today it is being used, indifferently, for both. No one can yet say whether this double power, forever growing, will lift us higher or shatter us in the end.","explanation_cn":"课文说所谓‘现代文明’不是人性均衡发展的果实,而只是投入日常生活的累积知识。✓ accumulated knowledge in practical life."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',10,NULL,'choice','{"stem":"How did the invention of writing help knowledge?","options":["It slowed knowledge down","Knowledge could be not only communicated but also stored","It replaced speech entirely","It made knowledge secret"],"answer_index":1,"audio":"Why does the idea of progress loom so large in the modern mind? Progress of one particular kind is certainly taking place all around us, and it grows more and more manifest with every passing year. In intelligence and in morality, it is true, the human race has hardly improved at all — a clever rogue of today is no wiser and no kinder than a clever rogue of three thousand years ago. Yet in one thing, the piling up of knowledge, mankind has advanced beyond all measure. Knowledge first began to grow the moment one person could communicate his thoughts to another by speech. When writing was invented, a far greater step was taken, for now knowledge could not only be passed on but also stored. Books made schools possible, and schools in their turn filled more books; so knowledge multiplied in the manner of compound interest, and the whole process was enormously enhanced by the coming of printing. For a long while the pace stayed slow; but with the rise of science the tempo was suddenly quickened, and knowledge began to pile up to a deliberate plan. What had been a trickle became a stream, and the stream has since swelled into a torrent. Better still, the instant any new knowledge is gained, it is at once turned to practical use. What we proudly call ''modern civilization'' is not, then, the fruit of a balanced growth of every side of human nature; it is simply stored-up knowledge put to work in daily life. And so a hard question now faces all of humanity: what are we to do with the mountain of knowledge we have raised? Knowledge, as people so often remark, is a two-edged weapon, equally fit for good or for evil; today it is being used, indifferently, for both. No one can yet say whether this double power, forever growing, will lift us higher or shatter us in the end.","explanation_cn":"课文说文字发明后,知识不仅能被传递,还能被储存,这是一大进步。✓ communicated and stored."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l22',10,NULL,'choice','{"stem":"What is knowledge compared to at the end?","options":["A two-edged weapon, usable for good or evil","A burning fire","A locked box","A quiet stream"],"answer_index":0,"audio":"Why does the idea of progress loom so large in the modern mind? Progress of one particular kind is certainly taking place all around us, and it grows more and more manifest with every passing year. In intelligence and in morality, it is true, the human race has hardly improved at all — a clever rogue of today is no wiser and no kinder than a clever rogue of three thousand years ago. Yet in one thing, the piling up of knowledge, mankind has advanced beyond all measure. Knowledge first began to grow the moment one person could communicate his thoughts to another by speech. When writing was invented, a far greater step was taken, for now knowledge could not only be passed on but also stored. Books made schools possible, and schools in their turn filled more books; so knowledge multiplied in the manner of compound interest, and the whole process was enormously enhanced by the coming of printing. For a long while the pace stayed slow; but with the rise of science the tempo was suddenly quickened, and knowledge began to pile up to a deliberate plan. What had been a trickle became a stream, and the stream has since swelled into a torrent. Better still, the instant any new knowledge is gained, it is at once turned to practical use. What we proudly call ''modern civilization'' is not, then, the fruit of a balanced growth of every side of human nature; it is simply stored-up knowledge put to work in daily life. And so a hard question now faces all of humanity: what are we to do with the mountain of knowledge we have raised? Knowledge, as people so often remark, is a two-edged weapon, equally fit for good or for evil; today it is being used, indifferently, for both. No one can yet say whether this double power, forever growing, will lift us higher or shatter us in the end.","explanation_cn":"课文结尾把知识比作一把双刃剑,同样可用于行善或作恶。✓ two-edged weapon."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l23',4,4,23,'Bird Flight','鸟的飞行','nor + 倒装(nor does it boast)、enough to do / 形容词 + enough + to do、such + 名词 + that … / so + 形容词 + that …、介词 + 关系代词(the engines with which…)、现在分词作状语(feeding its young…, slipping…)(NCE4 无 KS 页,考点由课文结构自取;IP:源为威廉·比奇·托马斯《乡下人的信条》,内容为‘鸟类两类飞行方式’的自然观察,已用 100% 原创行文复述,无逐句改写、无人物;题材=鸟的飞行·无害;美语化 airplane/curb;第四册第23课)','没有哪两种鸟飞得完全一样,花样多得数不清。可粗略地说,所有会飞的鸟都归入两大类。看一只信天翁跟着一条船横越大洋:它可以整整一个钟头与船并速前行,翅膀却看不出扇动一下。船身自己掀起的、以及沿着航线升起的那些气流,足以给这只翅膀巨大的大鸟提供它所需的一切养分与前进之力。信天翁是滑翔者之王——正是那一类会飞的鸟,把流动的空气驾驭为己所用;可一旦空气与它作对,它就只得让步。在相反的那一派里,鸭子至高无上。它更接近人用来“征服”天空的引擎。鸭子,连同鸽子,天生长着强壮的肌肉,几乎占了鸟身重量的一大部分;这些肌肉以势不可挡的力量扇动那对又短又硬的翅膀,以至于这鸟能笔直地冲过迎面的狂风,飞上好几英里,才终于精疲力竭。同类里更卑微的飞行者,比如鹧鸪,同样有强劲的推进力,却累得快得多;有时你能把一只捡起来——它已彻底累瘫,是被海上的一阵大风驱赶着飞了很远。也许最出色的飞行者要数燕子,它把两派的天赋都集于一身,发挥到极致。它似乎从不知疲倦,也无须硬闯;它索性就属于天空。它的本领是双重的——时而滑翔,时而扑翼——可以往返飞上几千英里,回到北方的巢,一路在空中喂养幼鸟,又那么轻盈地掠过天际,以至于我们几乎察觉不到它飞过。','{"q":"Listen and answer — What are the two main types of bird flight described by the author?","options":["Gliding, like the albatross, and wing-beating, like the duck","Flying and swimming","Fast and slow flight","Day flight and night flight"],"answer_index":0}'::jsonb,'{"title":"nor + 倒装 / enough to do / such·so … that / 介词+关系代词 / 现在分词作状语","intro":"①nor + 部分倒装,‘也不…’:nor does it boast。②enough to do;形容词 + enough + to do:strong enough to carry it。③such + 名词 + that …；so + 形容词 + that …。④介词 + 关系代词:the engines with which man conquered the sky。⑤现在分词作状语:crosses the sea, feeding its young on the wing。","table":{"headers":["用法","结构","例子"],"rows":[["nor + 倒装","nor + 助动词 + 主语","nor does it boast of its power"],["enough to do","形容词 + enough + to do","strong enough to carry it"],["such/so … that","such + 名词 / so + 形容词 + that","such force that it bores through gales"],["介词+关系代词","介词 + which","the engines with which man conquered the sky"],["现在分词状语","…, doing …","crosses the sea, feeding its young"]]},"specialRules":[{"rule":"nor / neither 置于句首时,后面要部分倒装(助动词提到主语前):nor does it boast。","mark":"nor + 助动词 + 主语"},{"rule":"so 修饰形容词/副词(so powerful that…);such 修饰名词短语(such force that…)。","mark":"so + 形容词 / such + 名词"},{"rule":"美式拼写:airplane(飞机,英式 aeroplane)、curb(路缘,英式 kerb)。本课已按美语写。","mark":"airplane / curb"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l23',1,NULL,'No two kinds of bird fly in quite the same manner; the varieties are past counting. Yet, roughly, all fliers fall into two great classes. Watch an albatross follow a ship across the ocean: for an hour together it may keep pace with the vessel without a single visible beat of its wings.','没有哪两种鸟飞得完全一样,花样多得数不清。可粗略地说,所有会飞的鸟都归入两大类。看一只信天翁跟着一条船横越大洋:它可以整整一个钟头与船并速前行,翅膀却看不出扇动一下。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l23',2,NULL,'The currents of air that the ship''s own sides throw upward, and those that rise along its path, are enough to give the huge bird, with its immense wings, all the sustenance and forward progress it needs. The albatross is the king of the gliders — that class of fliers which harness the moving air to their own purpose, yet must give way whenever the air turns against them.','船身自己掀起的、以及沿着航线升起的那些气流,足以给这只翅膀巨大的大鸟提供它所需的一切养分与前进之力。信天翁是滑翔者之王——正是那一类会飞的鸟,把流动的空气驾驭为己所用;可一旦空气与它作对,它就只得让步。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l23',3,NULL,'In the opposite school the duck is supreme. It comes far closer to the engines with which man has ''conquered'' the sky. A duck, and the pigeons with it, are endowed with powerful muscles that make up a good part of the bird''s whole weight; and these muscles ply the short, stiff wings with such irresistible force that the bird can bore for long miles straight through an opposing gale before exhaustion at last overtakes it.','在相反的那一派里,鸭子至高无上。它更接近人用来“征服”天空的引擎。鸭子,连同鸽子,天生长着强壮的肌肉,几乎占了鸟身重量的一大部分;这些肌肉以势不可挡的力量扇动那对又短又硬的翅膀,以至于这鸟能笔直地冲过迎面的狂风,飞上好几英里,才终于精疲力竭。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l23',4,NULL,'Humbler fliers of the same kind, such as the partridge, have the same strong propulsion but tire far sooner; you may sometimes pick one up in utter exhaustion after a hard wind has driven it out over the sea.','同类里更卑微的飞行者,比如鹧鸪,同样有强劲的推进力,却累得快得多;有时你能把一只捡起来——它已彻底累瘫,是被海上的一阵大风驱赶着飞了很远。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l23',5,NULL,'The finest flier of all, perhaps, is the swallow, which shares the gifts of both schools in the highest measure. It never seems to tire, nor does it need to force its way; it simply belongs to the air. Twofold in its powers — gliding and beating by turns — it may travel thousands of miles to its northern home and back, feeding its young on the wing and slipping so lightly through the sky that we scarcely notice it pass.','也许最出色的飞行者要数燕子,它把两派的天赋都集于一身,发挥到极致。它似乎从不知疲倦,也无须硬闯;它索性就属于天空。它的本领是双重的——时而滑翔,时而扑翼——可以往返飞上几千英里,回到北方的巢,一路在空中喂养幼鸟,又那么轻盈地掠过天际,以至于我们几乎察觉不到它飞过。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am4_l23','albatross','/ˈælbətrɔːs/','n','信天翁','watch an albatross follow a ship') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
