INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l23','keep pace with','',NULL,'/kiːp peɪs wɪð/','The albatross keeps pace with the ship.','信天翁与船并速前行。','I can''t keep pace with the changes.','我跟不上这些变化。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l23','give way','',NULL,'/ɡɪv weɪ/','The glider must give way to the wind.','滑翔者只得向风让步。','The old bridge gave way.','那座旧桥塌了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l23','bore through','',NULL,'/bɔːr θruː/','The duck bores through the gale.','鸭子冲过狂风。','The drill bores through rock.','钻头钻透岩石。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l23','on the wing','',NULL,'/ɑːn ðə wɪŋ/','It feeds its young on the wing.','它在飞行中喂养幼鸟。','The birds were on the wing at dawn.','拂晓时鸟儿都在飞。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp1','choice','{"stem":"\"The swallow never tires, ___ does it boast of its power.\"(‘也不…’,引起倒装的否定连词)","options":["nor","but","and","or"],"answer_index":0,"stem_cn":"燕子从不疲倦,也不炫耀自己的力量。","explanation_cn":"‘也不…’,引起部分倒装的否定连词是 nor。✓ never tires, nor does it boast. ✗ or / and / but:表‘也不’用 nor。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp1','choice','{"stem":"\"Nor ___ the albatross beat its wings much as it glides.\"(nor 引起倒装,填助动词)","options":["done","does","has","is"],"answer_index":1,"stem_cn":"信天翁滑翔时也不怎么扇翅膀。","explanation_cn":"nor 引起倒装,后接助动词 + 主语;一般现在时单数用 does。✓ Nor does the albatross beat its wings. ✗ is / has / done:此处倒装用 does + 原形。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp1','choice','{"stem":"\"The glider cannot fight the wind, nor ___ it wish to.\"(nor + 倒装,填助动词)","options":["does","has","done","is"],"answer_index":0,"stem_cn":"滑翔者无法对抗风,也不想去对抗。","explanation_cn":"nor 引起倒装,后接助动词 + 主语;一般现在时单数用 does。✓ nor does it wish to. ✗ is / has / done:此处倒装用 does。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp2','choice','{"stem":"\"The rising air is ___ to keep the great bird aloft.\"(‘足以做…’= ___ to do,填与 to 呼应的那个词)","options":["so","too","very","enough"],"answer_index":3,"stem_cn":"上升的气流足以让这大鸟保持在空中。","explanation_cn":"‘足以做…’= 形容词/副词 + enough + to do,或 be enough to do;与 to 呼应的那个词是 enough。✓ is enough to keep it aloft. ✗ too / very / so:表‘足够’用 enough。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp2','choice','{"stem":"\"The currents are strong ___ to carry it for hours.\"(strong … to do:‘强得足以…’,填 strong 后那个副词)","options":["enough","so","very","too"],"answer_index":0,"stem_cn":"气流强得足以带它飞好几个钟头。","explanation_cn":"strong + enough + to do,‘强得足以…’;strong 后那个副词是 enough。✓ strong enough to carry it. ✗ too / very / so:此结构用 enough。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp2','choice','{"stem":"\"Its wings are wide ___ to ride the smallest breeze.\"(wide … to do:‘宽得足以…’,填 wide 后那个副词)","options":["very","so","too","enough"],"answer_index":3,"stem_cn":"它的翅膀宽得足以借最微弱的风飞行。","explanation_cn":"wide + enough + to do,‘宽得足以…’;wide 后那个副词是 enough。✓ wide enough to ride the breeze. ✗ too / so / very:此结构用 enough。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp3','choice','{"stem":"\"The muscles ply the wings with ___ force that the bird bores through gales.\"(‘如此大的力量以至于…’,后接名词短语 force 时用的那个词)","options":["very","such","too","so"],"answer_index":1,"stem_cn":"肌肉以如此大的力量扇动翅膀,以至于鸟能冲过狂风。","explanation_cn":"‘如此大的力量以至于…’,后接名词短语 force,用 such。✓ with such force that … ✗ so / very / too:后接名词短语用 such。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp3','choice','{"stem":"\"It flies with ___ ease that no wind can stop it.\"(‘如此轻松以至于…’,后接名词 ease 时用的那个词)","options":["so","too","very","such"],"answer_index":3,"stem_cn":"它飞得如此轻松,没有风能拦住它。","explanation_cn":"‘如此轻松以至于…’,后接名词 ease,用 such。✓ with such ease that … ✗ so / very / too:后接名词用 such。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp3','choice','{"stem":"\"The duck''s muscles are ___ powerful that they weigh a lot.\"(‘如此…以至于’,修饰形容词 powerful 时用的那个词)","options":["too","so","such","very"],"answer_index":1,"stem_cn":"鸭子的肌肉如此强壮,以至于分量很重。","explanation_cn":"‘如此…以至于’,修饰形容词 powerful,用 so。✓ so powerful that they weigh a lot. ✗ such / very / too:修饰形容词用 so。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp4','choice','{"stem":"\"The engines ___ which man conquered the sky beat the air.\"(介词+关系代词;人‘用’引擎征服天空,填与 conquer 搭配的介词)","options":["with","of","in","at"],"answer_index":0,"stem_cn":"人用来征服天空的引擎,拍打着空气。","explanation_cn":"介词 + 关系代词;人‘用’引擎征服天空,conquer 搭配的介词是 with。✓ the engines with which man conquered the sky. ✗ of / at / in:表‘用…’用 with。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp4','choice','{"stem":"\"The purpose ___ which the bird harnesses the air is flight.\"(介词+关系代词,‘为了…’,填介词)","options":["with","at","for","of"],"answer_index":2,"stem_cn":"鸟驾驭气流所为的目的,就是飞行。","explanation_cn":"介词 + 关系代词;‘为了…的目的’,purpose 搭配 for。✓ the purpose for which … ✗ with / at / of:表‘为了’用 for。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp4','choice','{"stem":"\"The current ___ which it floats rises along the ship.\"(介词+关系代词;气流是它所漂浮其上的,填与 float 搭配的介词)","options":["of","on","for","at"],"answer_index":1,"stem_cn":"它所漂浮其上的气流,沿船身升起。","explanation_cn":"介词 + 关系代词;气流是它所漂浮其上的,float 搭配 on。✓ the current on which it floats. ✗ for / at / of:表‘在其上’用 on。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp5','choice','{"stem":"\"The swallow crosses the sea, ___ its young on the wing.\"(现在分词作状语,主动‘喂养’;feed 的 -ing)","options":["feed","to feed","fed","feeding"],"answer_index":3,"stem_cn":"燕子飞越大海,一边在空中喂养幼鸟。","explanation_cn":"现在分词作状语,主动‘喂养’;feed 的 -ing 形式。✓ crosses the sea, feeding its young. ✗ fed / feed / to feed:主动伴随用现在分词。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp5','choice','{"stem":"\"It slips through the sky, ___ so lightly we hardly see it.\"(现在分词作状语,主动‘滑行’;slip 的 -ing)","options":["slipping","to slip","slip","slipped"],"answer_index":0,"stem_cn":"它掠过天空,滑行得那么轻,我们几乎看不见。","explanation_cn":"现在分词作状语,主动‘滑行’;slip 的 -ing 形式。✓ slips through the sky, slipping so lightly. ✗ slipped / slip / to slip:主动伴随用现在分词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp5','choice','{"stem":"\"The albatross follows the ship, ___ pace for an hour.\"(现在分词作状语,主动‘保持’;keep 的 -ing)","options":["kept","to keep","keeping","keep"],"answer_index":2,"stem_cn":"信天翁跟着船,保持同速达一小时。","explanation_cn":"现在分词作状语,主动‘保持’;keep 的 -ing 形式。✓ follows the ship, keeping pace. ✗ kept / keep / to keep:主动伴随用现在分词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp6','choice','{"stem":"\"A bird or aircraft that flies without power, using air currents, is a ___.\"(“滑翔者/滑翔机”用哪个词)","options":["glider","rocket","balloon","engine"],"answer_index":0,"stem_cn":"不靠动力、借气流飞行的鸟或飞行器。","explanation_cn":"不靠动力、借气流飞行的鸟或飞行器是 glider(滑翔者/滑翔机)。✓ a flier that uses air currents is a glider. ✗ engine 引擎;✗ rocket 火箭;✗ balloon 气球——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp6','choice','{"stem":"\"A very strong wind is a ___.\"(“大风、狂风”用哪个词)","options":["cloud","breeze","mist","gale"],"answer_index":3,"stem_cn":"非常强劲的风。","explanation_cn":"非常强劲的风是 gale(大风、狂风)。✓ a very strong wind is a gale. ✗ breeze 微风;✗ cloud 云;✗ mist 薄雾——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',5,'am4_l23_gp6','choice','{"stem":"\"The food and support needed to stay alive is ___.\"(“养分、支撑”用哪个词)","options":["balance","distance","sustenance","silence"],"answer_index":2,"stem_cn":"维持生命所需的养分与支撑。","explanation_cn":"维持生命所需的养分与支撑是 sustenance。✓ food and support to stay alive is sustenance. ✗ distance 距离;✗ silence 寂静;✗ balance 平衡——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',6,NULL,'choice','{"stem":"albatross 的意思是:","options":["鸭子","信天翁","鹰","燕子"],"answer_index":1,"explanation_cn":"albatross = 信天翁。✓ watch an albatross follow a ship."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',6,NULL,'choice','{"stem":"glider 的意思是:","options":["游泳者","潜水员","滑翔者,滑翔机","跑步者"],"answer_index":2,"explanation_cn":"glider = 滑翔者、滑翔机。✓ the king of the gliders."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',6,NULL,'choice','{"stem":"harness 的意思是:","options":["驾驭,利用","浪费","释放","破坏"],"answer_index":0,"explanation_cn":"harness = 驾驭、利用。✓ harness the moving air."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',6,NULL,'choice','{"stem":"propulsion 的意思是:","options":["摩擦","阻力","推进,推进力","重力"],"answer_index":2,"explanation_cn":"propulsion = 推进、推进力。✓ the same strong propulsion."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',6,NULL,'choice','{"stem":"gale 的意思是:","options":["大风,狂风","薄雾","微风","细雨"],"answer_index":0,"explanation_cn":"gale = 大风、狂风。✓ through an opposing gale."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',6,NULL,'choice','{"stem":"utter 的意思是:","options":["部分的","温和的","短暂的","完全的,彻底的"],"answer_index":3,"explanation_cn":"utter = 完全的、彻底的。✓ in utter exhaustion."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',7,NULL,'cloze','{"stem":"第 1 空","context":"All fliers fall into two classes. The albatross is the king of the ___1___, harnessing the air. The duck is endowed ___2___ powerful muscles that ply its wings with ___3___ force that it bores through a gale. The swallow shares the gifts of both, ___4___ its young on the wing.","blank_no":1,"options":["gliders","glider","gliding","glide"],"answer_index":0,"explanation_cn":"the king of the gliders,滑翔者(复数)。✓ the king of the gliders."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',7,NULL,'cloze','{"stem":"第 2 空","context":"All fliers fall into two classes. The albatross is the king of the ___1___, harnessing the air. The duck is endowed ___2___ powerful muscles that ply its wings with ___3___ force that it bores through a gale. The swallow shares the gifts of both, ___4___ its young on the wing.","blank_no":2,"options":["with","of","at","in"],"answer_index":0,"explanation_cn":"be endowed with,‘天生具有’;固定搭配用 with。✓ endowed with powerful muscles."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',7,NULL,'cloze','{"stem":"第 3 空","context":"All fliers fall into two classes. The albatross is the king of the ___1___, harnessing the air. The duck is endowed ___2___ powerful muscles that ply its wings with ___3___ force that it bores through a gale. The swallow shares the gifts of both, ___4___ its young on the wing.","blank_no":3,"options":["such","so","very","too"],"answer_index":0,"explanation_cn":"such + 名词 + that …;后接名词 force 用 such。✓ ply its wings with such force that …"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',7,NULL,'cloze','{"stem":"第 4 空","context":"All fliers fall into two classes. The albatross is the king of the ___1___, harnessing the air. The duck is endowed ___2___ powerful muscles that ply its wings with ___3___ force that it bores through a gale. The swallow shares the gifts of both, ___4___ its young on the wing.","blank_no":4,"options":["feeding","fed","feed","to feed"],"answer_index":0,"explanation_cn":"现在分词作状语,主动‘喂养’。✓ shares the gifts of both, feeding its young."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',8,NULL,'choice','{"stem":"What are the two main types of bird flight described?","options":["High and low","Fast and slow","Gliding, like the albatross, and wing-beating, like the duck","Flying and swimming"],"answer_index":2,"explanation_cn":"录音说鸟的飞行大体分两类:像信天翁那样的滑翔,和像鸭子那样的扑翼。✓ gliding vs wing-beating."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',8,NULL,'choice','{"stem":"How does the albatross stay in the air for so long?","options":["It rides on other birds","It flaps its wings constantly","It rests on the ship","It harnesses the currents of air with its immense wings"],"answer_index":3,"explanation_cn":"录音说信天翁用巨大的翅膀驾驭气流,因此能长时间不扇翅膀地停在空中。✓ harnesses the currents of air."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',8,NULL,'choice','{"stem":"Why do humbler fliers like the partridge tire so quickly?","options":["They have strong propulsion but little endurance","They cannot glide at all","They never leave the ground","They have no muscles"],"answer_index":0,"explanation_cn":"录音说鹧鸪这类更卑微的飞行者虽有强劲推进力,却耐力很差,累得快。✓ strong propulsion but little endurance."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',9,NULL,'choice','{"stem":"你想说\"燕子从不疲倦,也不炫耀自己的力量\"(nor 倒装):","options":["The swallow never tires, nor it does boast of its power.","The swallow never tires, nor does it boast of its power.","The swallow never tires, or does it boast of its power.","The swallow never tires, nor does it boasts of its power."],"answer_index":1,"explanation_cn":"nor 引起部分倒装:nor + does + it(先 does 后 it,语序颠倒);boast 用原形(不写 boasts)、不写成 nor it does、也不用 or。✓ nor does it boast. 场合:说“…也不…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',9,NULL,'choice','{"stem":"你想说\"肌肉以如此大的力量扇动翅膀,以至于鸟能冲过狂风\"(such … that):","options":["The muscles ply the wings such with force that the bird bores through gales.","The muscles ply the wings with such force as the bird bores through gales.","The muscles ply the wings with so force that the bird bores through gales.","The muscles ply the wings with such force that the bird bores through gales."],"answer_index":3,"explanation_cn":"such + 名词短语 force + that …;修饰名词用 such(不用 so)、不写 such … as、such 紧靠名词短语(不写 such with force)。✓ with such force that … 场合:说“如此…以至于…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',9,NULL,'choice','{"stem":"你想说\"燕子飞越大海,一边在空中喂养幼鸟\"(现在分词作状语):","options":["The swallow crosses the sea, to feeding its young on the wing.","The swallow crosses the sea, fed its young on the wing.","The swallow crosses the sea, feeding its young on the wing.","The swallow crosses the sea, feed its young on the wing."],"answer_index":2,"explanation_cn":"现在分词 feeding 作伴随状语,主动;用 -ing(不用过去分词 fed、不用原形 feed、也不写 to feeding)。✓ …, feeding its young … 场合:主动的伴随动作。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',10,NULL,'choice','{"stem":"albatross 的意思是:","options":["鸭子","信天翁","鹰","燕子"],"answer_index":1,"explanation_cn":"albatross = 信天翁。✓ watch an albatross follow a ship."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',10,NULL,'choice','{"stem":"gale 的意思是:","options":["细雨","薄雾","微风","大风,狂风"],"answer_index":3,"explanation_cn":"gale = 大风、狂风。✓ through an opposing gale."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',10,NULL,'choice','{"stem":"\"The swallow never tires, ___ does it boast of its power.\"(‘也不…’,引起倒装的否定连词)","options":["and","nor","but","or"],"answer_index":1,"stem_cn":"燕子从不疲倦,也不炫耀力量。","explanation_cn":"‘也不…’,引起倒装的否定连词是 nor。✓ nor does it boast of its power. ✗ or / and / but。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',10,NULL,'choice','{"stem":"\"The muscles work with ___ force that the bird bores through gales.\"(‘如此大的力量’,后接名词短语)","options":["so","very","too","such"],"answer_index":3,"stem_cn":"肌肉以如此大的力量做工,鸟能冲过狂风。","explanation_cn":"‘如此大的力量’,后接名词短语用 such。✓ with such force that … ✗ so / very / too。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',10,NULL,'choice','{"stem":"\"keep pace with\" 的意思是:","options":["与…并驾齐驱、跟上","落后","停下","领先"],"answer_index":0,"explanation_cn":"keep pace with = 与…并驾齐驱、跟上。✓ the albatross keeps pace with the ship."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',10,NULL,'choice','{"stem":"\"on the wing\" 的意思是:","options":["在水里","在树上","在飞行中","在地上"],"answer_index":2,"explanation_cn":"on the wing = 在飞行中。✓ it feeds its young on the wing."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',10,NULL,'choice','{"stem":"According to the passage, what is the albatross the king of?","options":["The swimmers","The gliders, that harness the air to their purpose","The divers","The wing-beaters"],"answer_index":1,"passage":"No two kinds of bird fly in quite the same manner; the varieties are past counting. Yet, roughly, all fliers fall into two great classes. Watch an albatross follow a ship across the ocean: for an hour together it may keep pace with the vessel without a single visible beat of its wings. The currents of air that the ship''s own sides throw upward, and those that rise along its path, are enough to give the huge bird, with its immense wings, all the sustenance and forward progress it needs. The albatross is the king of the gliders — that class of fliers which harness the moving air to their own purpose, yet must give way whenever the air turns against them. In the opposite school the duck is supreme. It comes far closer to the engines with which man has ''conquered'' the sky. A duck, and the pigeons with it, are endowed with powerful muscles that make up a good part of the bird''s whole weight; and these muscles ply the short, stiff wings with such irresistible force that the bird can bore for long miles straight through an opposing gale before exhaustion at last overtakes it. Humbler fliers of the same kind, such as the partridge, have the same strong propulsion but tire far sooner; you may sometimes pick one up in utter exhaustion after a hard wind has driven it out over the sea. The finest flier of all, perhaps, is the swallow, which shares the gifts of both schools in the highest measure. It never seems to tire, nor does it need to force its way; it simply belongs to the air. Twofold in its powers — gliding and beating by turns — it may travel thousands of miles to its northern home and back, feeding its young on the wing and slipping so lightly through the sky that we scarcely notice it pass.","explanation_cn":"课文说信天翁是滑翔者之王——那类把流动空气驾驭为己所用的飞行者。✓ king of the gliders."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',10,NULL,'choice','{"stem":"How does the duck differ from the albatross?","options":["It is much smaller","It cannot fly at all","It never crosses water","It beats its wings with powerful muscles instead of gliding"],"answer_index":3,"passage":"No two kinds of bird fly in quite the same manner; the varieties are past counting. Yet, roughly, all fliers fall into two great classes. Watch an albatross follow a ship across the ocean: for an hour together it may keep pace with the vessel without a single visible beat of its wings. The currents of air that the ship''s own sides throw upward, and those that rise along its path, are enough to give the huge bird, with its immense wings, all the sustenance and forward progress it needs. The albatross is the king of the gliders — that class of fliers which harness the moving air to their own purpose, yet must give way whenever the air turns against them. In the opposite school the duck is supreme. It comes far closer to the engines with which man has ''conquered'' the sky. A duck, and the pigeons with it, are endowed with powerful muscles that make up a good part of the bird''s whole weight; and these muscles ply the short, stiff wings with such irresistible force that the bird can bore for long miles straight through an opposing gale before exhaustion at last overtakes it. Humbler fliers of the same kind, such as the partridge, have the same strong propulsion but tire far sooner; you may sometimes pick one up in utter exhaustion after a hard wind has driven it out over the sea. The finest flier of all, perhaps, is the swallow, which shares the gifts of both schools in the highest measure. It never seems to tire, nor does it need to force its way; it simply belongs to the air. Twofold in its powers — gliding and beating by turns — it may travel thousands of miles to its northern home and back, feeding its young on the wing and slipping so lightly through the sky that we scarcely notice it pass.","explanation_cn":"课文说鸭子与信天翁相反:它靠强壮的肌肉扇动翅膀推进,而不是滑翔。✓ beats its wings with powerful muscles."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',10,NULL,'choice','{"stem":"Which bird shares the gifts of both flying schools?","options":["The albatross","The swallow","The pigeon","The partridge"],"answer_index":1,"audio":"No two kinds of bird fly in quite the same manner; the varieties are past counting. Yet, roughly, all fliers fall into two great classes. Watch an albatross follow a ship across the ocean: for an hour together it may keep pace with the vessel without a single visible beat of its wings. The currents of air that the ship''s own sides throw upward, and those that rise along its path, are enough to give the huge bird, with its immense wings, all the sustenance and forward progress it needs. The albatross is the king of the gliders — that class of fliers which harness the moving air to their own purpose, yet must give way whenever the air turns against them. In the opposite school the duck is supreme. It comes far closer to the engines with which man has ''conquered'' the sky. A duck, and the pigeons with it, are endowed with powerful muscles that make up a good part of the bird''s whole weight; and these muscles ply the short, stiff wings with such irresistible force that the bird can bore for long miles straight through an opposing gale before exhaustion at last overtakes it. Humbler fliers of the same kind, such as the partridge, have the same strong propulsion but tire far sooner; you may sometimes pick one up in utter exhaustion after a hard wind has driven it out over the sea. The finest flier of all, perhaps, is the swallow, which shares the gifts of both schools in the highest measure. It never seems to tire, nor does it need to force its way; it simply belongs to the air. Twofold in its powers — gliding and beating by turns — it may travel thousands of miles to its northern home and back, feeding its young on the wing and slipping so lightly through the sky that we scarcely notice it pass.","explanation_cn":"课文说燕子把两派飞行的天赋都集于一身,发挥到极致。✓ the swallow shares the gifts of both schools."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l23',10,NULL,'choice','{"stem":"What powers the duck''s flight?","options":["Powerful muscles that ply its short wings","Its light weight","A following wind only","Air currents alone"],"answer_index":0,"audio":"No two kinds of bird fly in quite the same manner; the varieties are past counting. Yet, roughly, all fliers fall into two great classes. Watch an albatross follow a ship across the ocean: for an hour together it may keep pace with the vessel without a single visible beat of its wings. The currents of air that the ship''s own sides throw upward, and those that rise along its path, are enough to give the huge bird, with its immense wings, all the sustenance and forward progress it needs. The albatross is the king of the gliders — that class of fliers which harness the moving air to their own purpose, yet must give way whenever the air turns against them. In the opposite school the duck is supreme. It comes far closer to the engines with which man has ''conquered'' the sky. A duck, and the pigeons with it, are endowed with powerful muscles that make up a good part of the bird''s whole weight; and these muscles ply the short, stiff wings with such irresistible force that the bird can bore for long miles straight through an opposing gale before exhaustion at last overtakes it. Humbler fliers of the same kind, such as the partridge, have the same strong propulsion but tire far sooner; you may sometimes pick one up in utter exhaustion after a hard wind has driven it out over the sea. The finest flier of all, perhaps, is the swallow, which shares the gifts of both schools in the highest measure. It never seems to tire, nor does it need to force its way; it simply belongs to the air. Twofold in its powers — gliding and beating by turns — it may travel thousands of miles to its northern home and back, feeding its young on the wing and slipping so lightly through the sky that we scarcely notice it pass.","explanation_cn":"课文说鸭子的飞行靠强壮肌肉扇动那对又短又硬的翅膀。✓ muscles ply the short, stiff wings."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l24',4,4,24,'Beauty','美','it 作形式主语(It is difficult for us to do / It is unwise to do)、that 引导主语从句(That all great art has this power is undeniable)、非限定性定语从句(words, which were invented …, cannot…)、不定式作目的状语(invented to convey)、形容词/分词短语作状语(Unable to …, he concludes)(NCE4 无 KS 页,考点由课文结构自取;IP:源为 C.E.M. 乔德《Pieces of Mind》‘美’一文,内容为‘美的一瞥暗示更高之境、语言难以尽述’的美学随想,已用 100% 原创行文复述,无逐句改写、无人物;题材=审美体验·无害;美语化 color/favorite;第四册第24课)','设想一个年轻人望着夕阳西沉。他既说不清、也道不出那落日在心里激起的强烈情感,便断定这夕阳一定是通往我们世界之外某个天地的门。在强烈的审美体验里——面对一幅伟大的画、一段音乐、或一片夏日的天空——我们谁都很难抗拒同一种暗示:我们仿佛正瞥见一道光,从另一个存在之境照下来,一个不知怎地比此世更高的境界。一切伟大的艺术都有这种力量,这是不可否认的。在某些心境里,大自然也分享着它。六月的天空再蓝,也总指向一片更蓝;夕阳再美,也总唤起对一种更伟大之美的憧憬——那憧憬还没看清就已消逝,只留下一种说不清的怅惘。然而语言无法轻易承载这样的意义。词是为传达这个世界的事实而造的,难以套用到另一个世界上。我们似乎瞥见的那份宁静与光辉,大于我们所曾知道的,也大于我们所能描述的。也许这些‘身后、彼岸之物’的暗示根本无法解释。倘若美真有所指,我们也不该急着去解那意思。倘若我们瞥见了那不可言说之物,勉强去说它是不明智的,也不该给我们无法把握的东西强加意义。一颗庸俗的心也许会笑这些感受愚蠢,但更明智的做法,不过是领受这份美,任它如其所是。以我们平常那套人间意义去衡量,美,归根结底,是无意义的。','{"q":"Listen and answer — What do glimpses of beauty, either in nature or art, often suggest to the human mind?","options":["That there is a world beyond, somehow higher than our own","That beauty can be exactly measured","That art and nature are dangerous","That emotion should be avoided"],"answer_index":0}'::jsonb,'{"title":"it 形式主语 / that 主语从句 / 非限定定语从句 / 目的状语 to do / 形容词短语作状语","intro":"①it is + 形容词 +(for sb)+ to do:It is difficult for us to resist …。②that 引导从句置于句首作全句话题:That all great art has this power is undeniable。③非限定定语从句:words, which were invented …, cannot …。④不定式作目的状语:invented to convey the facts。⑤形容词/分词短语置于句首作状语:Unable to express the emotion, he concludes …。","table":{"headers":["用法","结构","例子"],"rows":[["it 形式主语","It is + 形容词 + to do","It is difficult for us to resist it"],["that 引导从句作话题","That … + is/are …","That great art has this power is undeniable"],["非限定定语从句",", which …,","words, which were invented …, cannot …"],["目的状语","to + 动词原形","invented to convey the facts"],["形容词短语作状语","Unable to do, …","Unable to express it, he fell silent"]]},"specialRules":[{"rule":"非限定性定语从句(前有逗号)指物时只能用 which,不能用 that。","mark":", which(≠ that)"},{"rule":"that 引导从句置于句首时本身无词义、不作成分;what 则要在从句里充当成分(the thing that)。","mark":"that ≠ what"},{"rule":"美式拼写:color(颜色,英式 colour)、favorite(最爱,英式 favourite)。本课已按美语写。","mark":"color / favorite"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l24',1,NULL,'Imagine a young man who watches the sun go down. Unable to understand or express the intense emotion it rouses in him, he concludes that the sunset must be a gateway to some world beyond our own.','设想一个年轻人望着夕阳西沉。他既说不清、也道不出那落日在心里激起的强烈情感,便断定这夕阳一定是通往我们世界之外某个天地的门。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l24',2,NULL,'In moments of strong aesthetic experience — before a great painting, a piece of music, or a summer sky — it is difficult for any of us to resist the same suggestion: that we are catching a glimpse of a light shining down from a different realm of existence, a realm somehow higher than this one.','在强烈的审美体验里——面对一幅伟大的画、一段音乐、或一片夏日的天空——我们谁都很难抗拒同一种暗示:我们仿佛正瞥见一道光,从另一个存在之境照下来,一个不知怎地比此世更高的境界。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l24',3,NULL,'That all great art has this power is undeniable. In certain moods, nature shares it too. There is no sky in June so blue that it does not point forward to a deeper blue, no sunset so beautiful that it does not waken the vision of a greater beauty — a vision that fades before it is fully seen, leaving behind an indefinable longing.','一切伟大的艺术都有这种力量,这是不可否认的。在某些心境里,大自然也分享着它。六月的天空再蓝,也总指向一片更蓝;夕阳再美,也总唤起对一种更伟大之美的憧憬——那憧憬还没看清就已消逝,只留下一种说不清的怅惘。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l24',4,NULL,'Yet words, which were invented to convey the facts of this world, cannot readily be fitted to the uses of another. The serenity and radiance we seem to glimpse are greater than we have ever known, and greater, too, than we can describe.','然而语言无法轻易承载这样的意义。词是为传达这个世界的事实而造的,难以套用到另一个世界上。我们似乎瞥见的那份宁静与光辉,大于我们所曾知道的,也大于我们所能描述的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l24',5,NULL,'Perhaps these intimations of something behind and beyond are not to be explained at all. If beauty truly means something, we must not rush to interpret that meaning. If we glimpse the unutterable, it is unwise to try to speak it, nor should we invest with false significance what we cannot grasp. Beauty measured in terms of our ordinary human meanings is, in the end, meaningless.','也许这些‘身后、彼岸之物’的暗示根本无法解释。倘若美真有所指,我们也不该急着去解那意思。倘若我们瞥见了那不可言说之物,勉强去说它是不明智的,也不该给我们无法把握的东西强加意义。以我们平常那套人间意义去衡量,美,归根结底,是无意义的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
