INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l24','catch a glimpse of','',NULL,'/kætʃ ə ɡlɪmps ʌv/','We catch a glimpse of a distant light.','我们瞥见一道远方的光。','I caught a glimpse of her in the crowd.','我在人群中瞥见了她。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l24','point forward to','',NULL,'/pɔɪnt ˈfɔːrwərd tuː/','No sky is so blue that it does not point forward to a bluer.','天空再蓝也总指向一片更蓝。','Every hint points forward to something greater.','每个暗示都指向更伟大之物。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l24','in terms of','',NULL,'/ɪn tɜːrmz ʌv/','Beauty in terms of human meaning is meaningless.','以人间意义衡量,美是无意义的。','Success in terms of money alone is empty.','只以金钱衡量的成功是空洞的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l24','invest with','',NULL,'/ɪnˈvest wɪð/','We should not invest it with false significance.','我们不该给它强加虚假的意义。','They invested the day with great meaning.','他们赋予那一天重大的意义。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp1','choice','{"stem":"\"___ is difficult for us to resist the suggestion of a higher world.\"(形式先行词占位,真正的内容是后面的不定式,填那个占位的代词)","options":["That","There","It","This"],"answer_index":2,"stem_cn":"我们很难抗拒‘有一个更高世界’的暗示。","explanation_cn":"形式先行词占位,真正要说的内容是后面的不定式 to resist …;句首用 It。✓ It is difficult for us to resist … ✗ That / This / There:占位用 It。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp1','choice','{"stem":"\"It is unwise ___ speak of what cannot be grasped.\"(形式先行词后接不定式,填不定式符号)","options":["to","for","of","at"],"answer_index":0,"stem_cn":"去言说那无法把握的东西是不明智的。","explanation_cn":"形式先行词后接不定式,填不定式符号 to。✓ It is unwise to speak of … ✗ for / at / of:不定式用 to。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp1','choice','{"stem":"\"It is hard ___ a young man to express such emotion.\"(‘对某人来说’,填介词)","options":["with","to","of","for"],"answer_index":3,"stem_cn":"对一个年轻人来说,表达这种情感很难。","explanation_cn":"‘对某人来说’在此结构里用 for(It is + 形容词 + for sb + to do)。✓ It is hard for a young man to express … ✗ to / of / with:‘对某人来说’用 for。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp2','choice','{"stem":"\"___ all great art has this power is undeniable.\"(引导从句置于句首、本身无词义的那个连词)","options":["What","Which","That","Whether"],"answer_index":2,"stem_cn":"一切伟大艺术都有这种力量,这是不可否认的。","explanation_cn":"引导从句置于句首、本身无词义、不作成分的那个连词是 That。✓ That all great art has this power is … ✗ What(要在从句里作成分)/ Which / Whether:此处用 That。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp2','choice','{"stem":"\"___ beauty points to a world beyond is felt by many.\"(引导从句置于句首的连词,本身不作成分)","options":["That","How","Which","What"],"answer_index":0,"stem_cn":"美指向一个彼岸世界——许多人都感受到这一点。","explanation_cn":"引导从句置于句首的连词,本身不作成分,用 That。✓ That beauty points to a world beyond is … ✗ What / Which / How:此处用 That。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp2','choice','{"stem":"\"It is undeniable ___ art suggests a greater beauty.\"(先行词占位、真正内容是后面从句,填引导该从句的连词)","options":["whether","what","that","which"],"answer_index":2,"stem_cn":"艺术暗示一种更伟大的美,这不可否认。","explanation_cn":"先行词 It 占位,真正内容是后面的从句;引导该从句的连词用 that。✓ It is undeniable that art suggests … ✗ what / which / whether:此处用 that。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp3','choice','{"stem":"\"Words, ___ were invented for this world, cannot describe another.\"(前有逗号的非限定定语从句,指物,填关系词)","options":["what","whose","that","which"],"answer_index":3,"stem_cn":"词是为这个世界而造的,无法描述另一个世界。","explanation_cn":"前有逗号的非限定定语从句,指物,只能用 which(不能用 that)。✓ Words, which were invented …, cannot … ✗ that / what / whose:非限定指物用 which。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp3','choice','{"stem":"\"The sunset, ___ rouses deep emotion, seems a gateway.\"(前有逗号的非限定定语从句,指物,填关系词)","options":["who","which","what","that"],"answer_index":1,"stem_cn":"落日唤起深深的情感,仿佛一道门。","explanation_cn":"前有逗号的非限定定语从句,指物,用 which。✓ The sunset, which rouses deep emotion, … ✗ that / who / what:非限定指物用 which。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp3','choice','{"stem":"\"He glimpsed a light, ___ passed before it was fully seen.\"(前有逗号的非限定定语从句,指物,填关系词)","options":["that","whose","which","who"],"answer_index":2,"stem_cn":"他瞥见一道光,还没看清就消逝了。","explanation_cn":"前有逗号的非限定定语从句,指物,用 which。✓ a light, which passed before it was fully seen. ✗ that / who / whose:非限定指物用 which。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp4','choice','{"stem":"\"Language was invented ___ convey the meanings of this world.\"(不定式作目的状语,‘为了传达’,填不定式符号)","options":["at","to","of","for"],"answer_index":1,"stem_cn":"语言的发明是为了传达这个世界的意义。","explanation_cn":"不定式作目的状语,‘为了传达’;填不定式符号 to。✓ invented to convey the meanings. ✗ for / at / of:目的状语用 to + 原形。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp4','choice','{"stem":"\"We should not seek ___ invest with meaning what we cannot grasp.\"(动词 seek 后面接的不定式,填其符号)","options":["to","for","in","at"],"answer_index":0,"stem_cn":"我们不该去给无法把握的东西强加意义。","explanation_cn":"seek 后面接不定式,填其符号 to。✓ seek to invest with meaning. ✗ for / at / in:seek to do。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp4','choice','{"stem":"\"He looked up ___ catch a glimpse of the fading light.\"(不定式作目的状语,‘为了瞥见’,填不定式符号)","options":["of","at","to","for"],"answer_index":2,"stem_cn":"他抬头,想瞥一眼渐暗的光。","explanation_cn":"不定式作目的状语,‘为了瞥见’;填不定式符号 to。✓ looked up to catch a glimpse. ✗ for / at / of:目的状语用 to。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp5','choice','{"stem":"\"___ to express the emotion, the young man fell silent.\"(形容词短语作状语,‘无法…做某事’,填表‘不能够’的形容词)","options":["Unable","Unkind","Unclear","Unfit"],"answer_index":0,"stem_cn":"无法表达这种情感,年轻人沉默了。","explanation_cn":"形容词短语作状语,‘无法做某事’;表‘不能够’的形容词是 Unable(+ to do)。✓ Unable to express the emotion, he fell silent. ✗ Unfit / Unkind / Unclear:‘无法…’用 Unable。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp5','choice','{"stem":"\"___ by the sudden radiance, she stood still.\"(过去分词短语作状语,被动‘被照得目眩’,填‘使目眩’那个词的过去分词)","options":["Dazzling","Dazzled","Dazzle","To dazzle"],"answer_index":1,"stem_cn":"被那突如其来的光辉照得目眩,她一动不动。","explanation_cn":"过去分词短语作状语,表被动‘被照得目眩’;填‘使目眩’那个词的过去分词。✓ Dazzled by the radiance, she stood still. ✗ 原形 / -ing(主动)/ to do:被动伴随用过去分词。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp5','choice','{"stem":"\"___ a light from another realm, he felt a strange longing.\"(现在分词短语作状语,主动,填‘瞥见’那个词的现在分词)","options":["Glimpsed","To glimpse","Glimpse","Glimpsing"],"answer_index":3,"stem_cn":"瞥见一道来自另一世界的光,他生出一种奇异的渴望。","explanation_cn":"现在分词短语作状语,主动‘瞥见’;填‘瞥见’那个词的现在分词。✓ Glimpsing a light …, he felt a longing. ✗ 过去分词(被动)/ 原形 / to do:主动伴随用现在分词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp6','choice','{"stem":"\"A feeling of calm and peace is ___.\"(“宁静、安详”用哪个词)","options":["poverty","serenity","cruelty","quantity"],"answer_index":1,"stem_cn":"平和安宁之感。","explanation_cn":"平和安宁之感是 serenity(宁静、安详)。✓ a feeling of calm and peace is serenity. ✗ cruelty 残忍;✗ poverty 贫穷;✗ quantity 数量——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp6','choice','{"stem":"\"Something that cannot be denied is ___.\"(“不可否认的”用哪个词)","options":["unequal","invisible","undeniable","unusual"],"answer_index":2,"stem_cn":"无法否认的。","explanation_cn":"无法被否认的是 undeniable(不可否认的)。✓ what cannot be denied is undeniable. ✗ invisible 看不见的;✗ unusual 不寻常的;✗ unequal 不平等的——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',5,'am4_l24_gp6','choice','{"stem":"\"A kingdom, or an area of activity or thought, is a ___.\"(“王国、领域”用哪个词)","options":["ritual","ruler","rumor","realm"],"answer_index":3,"stem_cn":"王国,或某一活动/思想的领域。","explanation_cn":"王国,或某一活动/思想的领域是 realm。✓ a kingdom or an area is a realm. ✗ rumor 谣言;✗ ruler 统治者;✗ ritual 仪式——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',6,NULL,'choice','{"stem":"aesthetic 的意思是:","options":["政治的","机械的","审美的,美学的","经济的"],"answer_index":2,"explanation_cn":"aesthetic = 审美的、美学的。✓ strong aesthetic experience."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',6,NULL,'choice','{"stem":"realm 的意思是:","options":["数量","王国,领域","距离","时刻"],"answer_index":1,"explanation_cn":"realm = 王国、领域、境界。✓ a different realm of existence."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',6,NULL,'choice','{"stem":"serenity 的意思是:","options":["愤怒","混乱","恐惧","宁静,安详"],"answer_index":3,"explanation_cn":"serenity = 宁静、安详。✓ the serenity and radiance we glimpse."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',6,NULL,'choice','{"stem":"vulgar 的意思是:","options":["高雅的","珍贵的","庸俗的,粗俗的","神圣的"],"answer_index":2,"explanation_cn":"vulgar = 庸俗的、粗俗的。✓ a vulgar mind may call it foolish."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',6,NULL,'choice','{"stem":"radiance 的意思是:","options":["阴影","光辉,光芒","雾气","黑暗"],"answer_index":1,"explanation_cn":"radiance = 光辉、光芒。✓ the serenity and radiance."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',6,NULL,'choice','{"stem":"intimation 的意思是:","options":["暗示,提示","证据","命令","结论"],"answer_index":0,"explanation_cn":"intimation = 暗示、提示。✓ these intimations of something beyond."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',7,NULL,'cloze','{"stem":"第 1 空","context":"A glimpse of beauty in nature or art suggests to the mind a world beyond. ___1___ all great art has this power is undeniable. Language, ___2___ was invented for this world, cannot describe another. ___3___ is difficult for us to express the feeling, yet ___4___ catch a glimpse of it is a kind of joy.","blank_no":1,"options":["That","What","Which","Whether"],"answer_index":0,"explanation_cn":"引导从句置于句首、本身无词义的连词用 That。✓ That all great art has this power is undeniable."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',7,NULL,'cloze','{"stem":"第 2 空","context":"A glimpse of beauty in nature or art suggests to the mind a world beyond. ___1___ all great art has this power is undeniable. Language, ___2___ was invented for this world, cannot describe another. ___3___ is difficult for us to express the feeling, yet ___4___ catch a glimpse of it is a kind of joy.","blank_no":2,"options":["which","that","who","what"],"answer_index":0,"explanation_cn":"前有逗号的非限定定语从句,指物,用 which。✓ Language, which was invented for this world, cannot …"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',7,NULL,'cloze','{"stem":"第 3 空","context":"A glimpse of beauty in nature or art suggests to the mind a world beyond. ___1___ all great art has this power is undeniable. Language, ___2___ was invented for this world, cannot describe another. ___3___ is difficult for us to express the feeling, yet ___4___ catch a glimpse of it is a kind of joy.","blank_no":3,"options":["It","That","This","There"],"answer_index":0,"explanation_cn":"形式先行词占位,真正内容是后面的不定式;句首用 It。✓ It is difficult for us to express the feeling."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',7,NULL,'cloze','{"stem":"第 4 空","context":"A glimpse of beauty in nature or art suggests to the mind a world beyond. ___1___ all great art has this power is undeniable. Language, ___2___ was invented for this world, cannot describe another. ___3___ is difficult for us to express the feeling, yet ___4___ catch a glimpse of it is a kind of joy.","blank_no":4,"options":["to","for","at","of"],"answer_index":0,"explanation_cn":"不定式作全句话题,‘去瞥见…是一种乐趣’;填不定式符号 to。✓ to catch a glimpse of it is a kind of joy."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',8,NULL,'choice','{"stem":"What do glimpses of beauty often suggest to the human mind?","options":["A world beyond, higher than our own","That art is useless","That beauty can be measured","That nature is dangerous"],"answer_index":0,"explanation_cn":"录音说无论在自然还是艺术中,美的一瞥常常向人暗示:存在一个比此世更高的彼岸世界。✓ a world beyond, higher than our own."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',8,NULL,'choice','{"stem":"Why can language not fully describe this beauty?","options":["Beauty makes people silent","People speak too quickly","It was invented to convey the meanings of this world, not another","It has too few words"],"answer_index":2,"explanation_cn":"录音说语言是为传达‘这个世界’的意义而造的,难以套用到另一个世界上,所以无法尽述那份美。✓ invented for this world, not another."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',8,NULL,'choice','{"stem":"According to the speaker, what is unwise?","options":["To look at a sunset","To try to utter what we cannot grasp","To feel deep emotion","To enjoy great art"],"answer_index":1,"explanation_cn":"录音说勉强去言说我们无法把握的东西,是不明智的。✓ unwise to utter what we cannot grasp."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',9,NULL,'choice','{"stem":"你想说\"我们很难抗拒那种暗示\"(用 it 作先行占位、真正内容后置):","options":["It is difficult for us resisting the suggestion.","Is difficult for us to resist the suggestion.","It is difficult for us to resist the suggestion.","It is difficult of us to resist the suggestion."],"answer_index":2,"explanation_cn":"句首 It 作先行占位,真正内容后置为不定式 to resist;不能省 It(不写 Is difficult…)、‘对我们’用 for us(不用 of us)、后接 to do 不用 -ing(不写 resisting)。✓ It is difficult for us to resist … 场合:说“(做某事)对我们很难”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',9,NULL,'choice','{"stem":"你想说\"一切伟大艺术都有这种力量,这是不可否认的\"(that 引导从句置于句首作全句话题):","options":["That all great art has this power is undeniable.","Which all great art has this power is undeniable.","What all great art has this power is undeniable.","That all great art has this power are undeniable."],"answer_index":0,"explanation_cn":"That 引导一整句内容置于句首作全句的话题;用 That(不用 What/Which)、全句动词用单数 is(不用 are)。✓ That … is undeniable. 场合:把“某件事”作为话题提到句首。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',9,NULL,'choice','{"stem":"你想说\"无法表达那种情感,年轻人沉默了\"(形容词短语作状语):","options":["Unable express the emotion, the young man fell silent.","Unable to express the emotion, the young man fell silent.","Unable to expressing the emotion, the young man fell silent.","Unable to express the emotion, the young man fell silently."],"answer_index":1,"explanation_cn":"Unable to do 短语置于句首作状语;Unable 后接 to + 原形 express(不省 to、不写 expressing)、fell 后接形容词 silent(不用副词 silently)。✓ Unable to express …, he fell silent. 场合:用短语说明“因无法…而…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',10,NULL,'choice','{"stem":"realm 的意思是:","options":["王国,领域","数量","时刻","距离"],"answer_index":0,"explanation_cn":"realm = 王国、领域、境界。✓ a different realm of existence."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',10,NULL,'choice','{"stem":"serenity 的意思是:","options":["混乱","恐惧","宁静,安详","愤怒"],"answer_index":2,"explanation_cn":"serenity = 宁静、安详。✓ the serenity and radiance we glimpse."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',10,NULL,'choice','{"stem":"\"___ all great art has this power is undeniable.\"(引导从句置于句首、本身无词义的连词)","options":["Which","That","What","Whether"],"answer_index":1,"stem_cn":"一切伟大艺术都有这种力量,这不可否认。","explanation_cn":"引导从句置于句首、本身无词义的连词用 That。✓ That all great art has this power is undeniable. ✗ What / Which / Whether。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',10,NULL,'choice','{"stem":"\"Language, ___ was invented for this world, cannot describe another.\"(前有逗号的非限定定语从句,指物)","options":["that","who","what","which"],"answer_index":3,"stem_cn":"语言是为这个世界而造的,无法描述另一个世界。","explanation_cn":"前有逗号的非限定定语从句,指物,用 which。✓ Language, which was invented …, cannot … ✗ that / who / what。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',10,NULL,'choice','{"stem":"\"catch a glimpse of\" 的意思是:","options":["紧盯","瞥见","记住","忽视"],"answer_index":1,"explanation_cn":"catch a glimpse of = 瞥见。✓ we catch a glimpse of a distant light."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',10,NULL,'choice','{"stem":"\"in terms of\" 的意思是:","options":["除了","为了","反对","就…而言,从…角度"],"answer_index":3,"explanation_cn":"in terms of = 就…而言、从…角度。✓ beauty in terms of human meaning is meaningless."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',10,NULL,'choice','{"stem":"What does a glimpse of beauty suggest to the young man?","options":["That the sunset is a gateway to a world beyond","That emotion is dangerous","That the sunset is ordinary","That art has no value"],"answer_index":0,"passage":"Imagine a young man who watches the sun go down. Unable to understand or express the intense emotion it rouses in him, he concludes that the sunset must be a gateway to some world beyond our own. In moments of strong aesthetic experience — before a great painting, a piece of music, or a summer sky — it is difficult for any of us to resist the same suggestion: that we are catching a glimpse of a light shining down from a different realm of existence, a realm somehow higher than this one. That all great art has this power is undeniable. In certain moods, nature shares it too. There is no sky in June so blue that it does not point forward to a deeper blue, no sunset so beautiful that it does not waken the vision of a greater beauty — a vision that fades before it is fully seen, leaving behind an indefinable longing. Yet words, which were invented to convey the facts of this world, cannot readily be fitted to the uses of another. The serenity and radiance we seem to glimpse are greater than we have ever known, and greater, too, than we can describe. Perhaps these intimations of something behind and beyond are not to be explained at all. If beauty truly means something, we must not rush to interpret that meaning. If we glimpse the unutterable, it is unwise to try to speak it, nor should we invest with false significance what we cannot grasp. A vulgar mind may call such feelings foolish, but the wiser course is simply to receive the beauty and let it be. Beauty measured in terms of our ordinary human meanings is, in the end, meaningless.","explanation_cn":"课文说年轻人无法理解落日激起的强烈情感,便断定它是通往彼岸世界的门。✓ a gateway to some world beyond."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',10,NULL,'choice','{"stem":"Why does the author say language cannot describe this beauty?","options":["The beauty is too small","Language was made for this world, not for another","People are not clever enough","No one has tried"],"answer_index":1,"passage":"Imagine a young man who watches the sun go down. Unable to understand or express the intense emotion it rouses in him, he concludes that the sunset must be a gateway to some world beyond our own. In moments of strong aesthetic experience — before a great painting, a piece of music, or a summer sky — it is difficult for any of us to resist the same suggestion: that we are catching a glimpse of a light shining down from a different realm of existence, a realm somehow higher than this one. That all great art has this power is undeniable. In certain moods, nature shares it too. There is no sky in June so blue that it does not point forward to a deeper blue, no sunset so beautiful that it does not waken the vision of a greater beauty — a vision that fades before it is fully seen, leaving behind an indefinable longing. Yet words, which were invented to convey the facts of this world, cannot readily be fitted to the uses of another. The serenity and radiance we seem to glimpse are greater than we have ever known, and greater, too, than we can describe. Perhaps these intimations of something behind and beyond are not to be explained at all. If beauty truly means something, we must not rush to interpret that meaning. If we glimpse the unutterable, it is unwise to try to speak it, nor should we invest with false significance what we cannot grasp. A vulgar mind may call such feelings foolish, but the wiser course is simply to receive the beauty and let it be. Beauty measured in terms of our ordinary human meanings is, in the end, meaningless.","explanation_cn":"课文说语言是为传达这个世界的事实而造的,难以套用到另一个世界,故无法描述那份美。✓ invented for this world."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',10,NULL,'choice','{"stem":"What is unwise, according to the speaker?","options":["To feel moved by music","To read poetry","To watch a sunset","To try to utter what we cannot grasp"],"answer_index":3,"audio":"Imagine a young man who watches the sun go down. Unable to understand or express the intense emotion it rouses in him, he concludes that the sunset must be a gateway to some world beyond our own. In moments of strong aesthetic experience — before a great painting, a piece of music, or a summer sky — it is difficult for any of us to resist the same suggestion: that we are catching a glimpse of a light shining down from a different realm of existence, a realm somehow higher than this one. That all great art has this power is undeniable. In certain moods, nature shares it too. There is no sky in June so blue that it does not point forward to a deeper blue, no sunset so beautiful that it does not waken the vision of a greater beauty — a vision that fades before it is fully seen, leaving behind an indefinable longing. Yet words, which were invented to convey the facts of this world, cannot readily be fitted to the uses of another. The serenity and radiance we seem to glimpse are greater than we have ever known, and greater, too, than we can describe. Perhaps these intimations of something behind and beyond are not to be explained at all. If beauty truly means something, we must not rush to interpret that meaning. If we glimpse the unutterable, it is unwise to try to speak it, nor should we invest with false significance what we cannot grasp. A vulgar mind may call such feelings foolish, but the wiser course is simply to receive the beauty and let it be. Beauty measured in terms of our ordinary human meanings is, in the end, meaningless.","explanation_cn":"课文结尾说:若瞥见那不可言说之物,勉强去说它是不明智的。✓ unwise to try to utter it."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l24',10,NULL,'choice','{"stem":"Where can glimpses of beauty be found?","options":["In both nature and art","Nowhere at all","Only in books","Only in museums"],"answer_index":0,"audio":"Imagine a young man who watches the sun go down. Unable to understand or express the intense emotion it rouses in him, he concludes that the sunset must be a gateway to some world beyond our own. In moments of strong aesthetic experience — before a great painting, a piece of music, or a summer sky — it is difficult for any of us to resist the same suggestion: that we are catching a glimpse of a light shining down from a different realm of existence, a realm somehow higher than this one. That all great art has this power is undeniable. In certain moods, nature shares it too. There is no sky in June so blue that it does not point forward to a deeper blue, no sunset so beautiful that it does not waken the vision of a greater beauty — a vision that fades before it is fully seen, leaving behind an indefinable longing. Yet words, which were invented to convey the facts of this world, cannot readily be fitted to the uses of another. The serenity and radiance we seem to glimpse are greater than we have ever known, and greater, too, than we can describe. Perhaps these intimations of something behind and beyond are not to be explained at all. If beauty truly means something, we must not rush to interpret that meaning. If we glimpse the unutterable, it is unwise to try to speak it, nor should we invest with false significance what we cannot grasp. A vulgar mind may call such feelings foolish, but the wiser course is simply to receive the beauty and let it be. Beauty measured in terms of our ordinary human meanings is, in the end, meaningless.","explanation_cn":"课文开篇即说,美的一瞥可以来自自然(如落日、夏空),也可以来自艺术(如画、音乐)。✓ in nature or art."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
